export const macroQuestionPool: MacroQuestion[] = [
  // ── Domain: basic-concepts · macro-scarcity-opportunity-cost ─────────
  { question: 'A bakery buys a new commercial oven to expand production. In economics, the oven is classified as which factor of production?', options: ['Labor', 'Capital', 'Land', 'Entrepreneurship'], correctAnswer: 1, explanation: 'Capital is a manufactured tool or machine used to produce other goods, so an oven is capital. Land refers to natural resources, labor is human effort, and entrepreneurship is the risk-taking that combines the other factors.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'Maya can spend Saturday tutoring for \\$60, babysitting for \\$45, or volunteering at an animal shelter, which she values at \\$30. She chooses to tutor. What is her opportunity cost?', options: ['The \\$75 combined value of babysitting and volunteering', 'The \\$60 she earns from tutoring on Saturday', 'The \\$45 she could have earned babysitting', 'The \\$30 value she places on shelter volunteering'], correctAnswer: 2, explanation: 'Opportunity cost is the value of the single next-best alternative, which is babysitting at \\$45. It never adds up all the forgone options, it is not the payoff of the option chosen, and volunteering is only the third-best choice.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  { question: 'On a production possibilities curve for robots and wheat, a point lying beyond the curve represents a combination that is', options: ['efficient, using all resources fully', 'inefficient, leaving some resources idle', 'attainable only after resources are reallocated', 'unattainable with current resources and technology'], correctAnswer: 3, explanation: 'Points outside the PPC cannot be produced with the resources and technology the economy has now. Points on the curve are efficient, points inside are inefficient, and reallocating existing resources only moves the economy along or onto the curve, never beyond it.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'A country\'s PPC includes point J (60 tractors, 200 tons of corn) and point K (75 tractors, 150 tons of corn). Moving from J to K, what is the opportunity cost of each additional tractor?', options: ['50 tons of corn', '15 tons of corn', '3.3 tons of corn', '0.3 tons of corn'], correctAnswer: 2, explanation: 'The move gives up 50 tons of corn to gain 15 tractors, so each tractor costs 50 ÷ 15 ≈ 3.3 tons of corn. Fifty tons is the total sacrifice rather than the per-unit cost, 15 is the change in tractors, and 0.3 inverts the ratio (it is the cost of a ton of corn in tractors).', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  { question: 'A nation\'s PPC for medical care and housing is bowed outward from the origin. What best explains this shape?', options: ['Resources are not equally suited to producing both goods', 'Each input is perfectly interchangeable between the goods', 'The economy is producing inside its production frontier', 'Technology improves as more of either good is produced'], correctAnswer: 0, explanation: 'A bowed-out PPC reflects increasing opportunity cost: as production shifts toward one good, the economy must use resources that are less suited to it. Perfectly interchangeable resources would give a straight line, producing inside the frontier says nothing about its shape, and technology change shifts the curve rather than bending it.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'Country Z\'s PPC is a straight line running from 400 pens (and no pencils) to 800 pencils (and no pens). The opportunity cost of producing pens is best described as', options: ['2 pencils per pen at every output level', '0.5 pencils per pen at every output level', 'More pencils per pen as pen output rises', 'Fewer pencils per pen as pen output rises'], correctAnswer: 0, explanation: 'Giving up all 800 pencils yields 400 pens, so each pen costs 800 ÷ 400 = 2 pencils, and a straight-line PPC means that cost is constant. The 0.5 figure is the cost of a pencil measured in pens, and rising or falling costs would require a curved PPC.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  { question: 'A country discovers large new deposits of natural gas and trains thousands of additional engineers. On its PPC, this is best shown as', options: ['a movement along the curve toward capital goods', 'an outward shift of the entire curve', 'a movement from inside the curve onto it', 'an inward shift of the entire curve'], correctAnswer: 1, explanation: 'More natural resources and more skilled labor raise the economy\'s maximum possible output, shifting the whole PPC outward. Moving along the curve or from inside onto it uses existing resources differently, and an inward shift would mean resources were lost.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'A new seed variety raises farm yields but has no effect on factory output. On a PPC with agricultural goods on the horizontal axis and manufactured goods on the vertical axis, the curve will', options: ['shift outward by the same amount on both axes', 'pivot out on the factory axis, same farm intercept', 'remain fixed while output moves along it', 'reach farther on the farm axis, same factory intercept'], correctAnswer: 3, explanation: 'A technology gain in only one sector moves only that good\'s intercept, so the curve reaches farther along the agricultural axis while the manufactured-goods intercept stays put. A parallel shift requires gains in both sectors, the vertical intercept depends on factory productivity, and a change in technology always moves the frontier itself.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  { question: 'Farm productivity doubles in Agraria while its factory productivity is unchanged. What happens to Agraria\'s opportunity cost of producing one unit of manufactured goods?', options: ['It stays the same, because factory productivity is unchanged', 'It falls, because crops are now cheaper to produce than before', 'It falls, because the whole economy can now produce more output', 'It rises, because each factory good now costs more crops'], correctAnswer: 3, explanation: 'The resources used to make one factory good could now grow twice as many crops, so each manufactured good costs more crops than before. Opportunity cost depends on both sectors, not just the factory sector; crops becoming cheaper describes the cost of crops, not of factory goods; and a larger frontier does not lower the cost of the unchanged good.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'Which situation best illustrates the economic concept of scarcity?', options: ['A store briefly runs out of a toy after cutting its price', 'A town has more demands on its budget than funds to meet them', 'A family decides to rent an apartment rather than buy a home', 'A firm earns lower profits this year than it did last year'], correctAnswer: 1, explanation: 'Scarcity means limited resources cannot satisfy all wants, as when a town\'s needs exceed its funds. A store running out after a price cut is a temporary shortage caused by a price below equilibrium, while the renting decision and lower profits are outcomes of choices, not the underlying problem of limited resources.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  { question: 'A farmer leases 40 acres of her land to a solar company. The lease payments she receives are an example of which factor payment?', options: ['Wages', 'Interest', 'Rent', 'Profit'], correctAnswer: 2, explanation: 'Rent is the payment to owners of land and other natural resources. Wages go to labor, interest goes to owners of capital, and profit rewards entrepreneurship.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'During a severe recession, many factories sit idle and unemployment rises sharply. On the country\'s PPC, the economy is best represented by', options: ['a point inside the curve', 'an inward shift of the curve', 'a point on the curve itself', 'an outward shift of the curve'], correctAnswer: 0, explanation: 'Idle factories and unemployed workers mean the economy produces less than it could, which is a point inside the PPC. The curve itself shifts inward only if resources are destroyed or lost, a point on the curve means full use of resources, and an outward shift reflects growth.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  { question: 'A PPC table lists four points for guns and butter: (0 guns, 100 butter), (10, 90), (20, 70), and (30, 40). What is the opportunity cost of raising gun output from 20 to 30?', options: ['40 units of butter', '30 units of butter', '60 units of butter', '10 units of butter'], correctAnswer: 1, explanation: 'Butter output falls from 70 to 40, so the 10 extra guns cost 30 units of butter. Forty is the butter still produced at the new point, 60 is the total butter given up since zero guns, and 10 is the change in guns.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'Country A devotes a larger share of its resources to capital goods than Country B, which favors consumer goods. All else equal, what does the PPC model predict for the future?', options: ['B\'s PPC will likely shift outward farther than A\'s', 'Both PPCs will shift outward by the same amount', 'A\'s PPC will likely shift outward farther than B\'s', 'A\'s PPC will shift inward as its consumption falls'], correctAnswer: 2, explanation: 'Capital goods such as factories and machinery raise future productive capacity, so the country that invests more in them should grow faster. Favoring consumer goods raises current living standards but adds less to future capacity, and lower current consumption does not shrink the frontier.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  { question: 'If the opportunity cost of producing 1 bicycle is 4 scooters, the opportunity cost of producing 1 scooter is', options: ['4 bicycles', '1 bicycle', '0.4 bicycles', '0.25 bicycles'], correctAnswer: 3, explanation: 'Opportunity costs for the two goods are reciprocals, so one scooter costs 1 ÷ 4 = 0.25 bicycles. Four bicycles repeats the original number in the wrong units, one bicycle ignores the ratio, and 0.4 misplaces the decimal.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 1, part: 1 },
  { question: 'An economy moves from (50 capital goods, 300 consumer goods) to (60, 260) and then to (70, 200). Each step adds 10 capital goods. What does this pattern illustrate?', options: ['Constant opportunity cost of capital goods', 'Increasing opportunity cost of capital goods', 'Decreasing opportunity cost of capital goods', 'Economic growth shifting the curve outward'], correctAnswer: 1, explanation: 'The first 10 capital goods cost 40 consumer goods and the next 10 cost 60, so each additional unit costs more: increasing opportunity cost. A constant cost would mean equal sacrifices each step, a decreasing cost would mean smaller ones, and all three points can lie on one curve, so no growth is shown.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'macro-scarcity-opportunity-cost', formSet: 2, part: 1 },
  // ── Domain: basic-concepts · macro-comparative-advantage ─────────────
  { question: 'In one day, Lena can bake 20 loaves of bread or knit 4 scarves. Omar can bake 10 loaves or knit 4 scarves. Who has the comparative advantage in scarves?', options: ['Omar, because his cost per scarf is 2.5 loaves', 'Lena, because her cost per scarf is 5 loaves', 'Neither, because both knit 4 scarves a day', 'Lena, because she has the absolute advantage in bread'], correctAnswer: 0, explanation: 'A scarf costs Omar 10 ÷ 4 = 2.5 loaves but costs Lena 20 ÷ 4 = 5 loaves, so Omar has the lower opportunity cost. Equal scarf output says nothing about opportunity cost, and an absolute advantage in bread actually makes scarves more costly for Lena.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  { question: 'A Brazilian coffee worker harvests 50 tons a year, while a Vietnamese coffee worker harvests 30 tons. Based only on this information, Brazil has', options: ['a comparative advantage in coffee', 'both kinds of advantage in coffee', 'a lower opportunity cost of coffee', 'an absolute advantage in coffee'], correctAnswer: 3, explanation: 'Producing more of a good with the same resources is an absolute advantage. Comparative advantage and opportunity cost require knowing what each worker gives up, which needs data on a second good, so neither can be determined here.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'A worker in Country P can make 12 phones or 36 shirts per week. A worker in Country Q can make 4 phones or 24 shirts. Which pattern of specialization maximizes the gains from trade?', options: ['P makes shirts and Q makes phones', 'P makes phones and Q makes shirts', 'P makes both goods and Q makes none', 'Each makes half phones and half shirts'], correctAnswer: 1, explanation: 'A phone costs P 3 shirts but costs Q 6 shirts, so P should make phones; a shirt costs Q only 1/6 phone versus 1/3 phone in P, so Q should make shirts. Reversing the roles raises costs, and having P make everything or splitting output evenly gives up the gains from specialization.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'In Country P, one phone costs 3 shirts in forgone output; in Country Q, one phone costs 6 shirts. Which terms of trade would benefit both countries?', options: ['1 phone for 2 shirts', '1 phone for 4 shirts', '1 phone for 7 shirts', '1 phone for 9 shirts'], correctAnswer: 1, explanation: 'Mutually beneficial terms must lie between the two opportunity costs, 3 and 6 shirts per phone, and only 4 shirts does. At 2 shirts the phone exporter (P) would be better off making shirts itself, and at 7 or 9 shirts the importer (Q) would rather make its own phones.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  { question: 'In Country R, producing 1 ton of steel costs 4 tons of rice; in Country S, it costs 1.5 tons of rice. Which price of rice, stated in steel, lets both countries gain from trade?', options: ['0.2 tons of steel per ton of rice', '1.5 tons of steel per ton of rice', '0.5 tons of steel per ton of rice', '0.8 tons of steel per ton of rice'], correctAnswer: 2, explanation: 'Inverting the steel costs, a ton of rice costs R 0.25 steel and costs S about 0.67 steel, so the price must fall between those values; 0.5 does. A price of 0.2 is below R\'s cost, 0.8 is above S\'s cost, and 1.5 is a steel-for-rice figure from the stem placed in the wrong units.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'Two countries specialize according to comparative advantage and trade at mutually beneficial terms. As a result, each country can', options: ['consume at a point outside its own PPC', 'produce at a point outside its own PPC', 'consume only at a point on its own PPC', 'produce more of both goods at home'], correctAnswer: 0, explanation: 'Trade lets each country consume combinations it could not produce alone, which lie beyond its PPC. Production stays on or inside each country\'s PPC, and specializing means each country produces more of one good and less of the other.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  { question: 'Country M can produce more cars and more grain than Country N with the same resources. Which statement about trade between them is correct?', options: ['Only M can gain, since it is more productive in both goods', 'Neither can gain, since M can make everything on its own', 'Each can gain by specializing where its opportunity cost is lower', 'Only N can gain, since it receives cheaper goods from M'], correctAnswer: 2, explanation: 'Gains from trade come from differences in opportunity cost, not from absolute productivity, so both countries can benefit even though M has an absolute advantage in both goods. Claims that only one side or neither side gains confuse absolute advantage with comparative advantage.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'Country F can produce 30 rugs or 10 lamps; Country G can produce 60 rugs or 20 lamps. What can be concluded?', options: ['G has a comparative advantage in both goods', 'Neither has a comparative advantage, so trade adds nothing', 'F has a comparative advantage in lamps', 'G has a comparative advantage in lamps only'], correctAnswer: 1, explanation: 'A lamp costs 3 rugs in both countries, so their opportunity costs are identical and specialization creates no gains. G has an absolute advantage in both goods, but no producer can hold a comparative advantage in both, and with equal costs neither holds one in lamps.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  { question: 'Country T needs 2 labor hours to make a bike and 4 hours to make a desk. Country U needs 6 hours per bike and 3 hours per desk. Which country has the comparative advantage in desks, and what is its opportunity cost of a desk?', options: ['2 bikes per desk, in Country T', '0.5 bikes per desk, in Country T', '2 bikes per desk, in Country U', '0.5 bikes per desk, in Country U'], correctAnswer: 3, explanation: 'With input data, the opportunity cost of a desk is its hours divided by the hours for a bike: 4 ÷ 2 = 2 bikes in T and 3 ÷ 6 = 0.5 bikes in U, so U has the advantage. Assigning 0.5 to T flips the ratio, which is a common error when the table lists hours rather than output.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'According to the principle of comparative advantage, which comparison determines what each country should produce?', options: ['Opportunity cost of each good', 'Total output of each good', 'Output per worker of each good', 'Money price of each good'], correctAnswer: 0, explanation: 'Comparative advantage compares opportunity costs, meaning what each producer gives up. Total output and output per worker describe absolute advantage, and money prices can differ for reasons unrelated to the real trade-off.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  { question: 'Wages in Country H are far below those in Country K for every kind of work. A politician argues that K cannot benefit from trading with H. Which response best reflects comparative advantage?', options: ['K gains only if its wages fall to match H\'s wages', 'K loses unless it holds an absolute advantage', 'K loses because low wages beat high productivity', 'Trade lets K buy goods whose opportunity cost is high at home'], correctAnswer: 3, explanation: 'K benefits by importing goods that would require it to give up a lot to make domestically and exporting goods it makes at relatively low opportunity cost. Gains do not require equal wages or an absolute advantage, and wage levels alone do not decide the pattern of trade.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'Using all its resources, Country V can make 100 tons of fish or 50 computers; Country W can make 80 tons of fish or 80 computers. Which statement is true?', options: ['V has a comparative advantage in computers', 'W has an absolute advantage in fish', 'V has a comparative advantage in fish', 'W has a comparative advantage in fish'], correctAnswer: 2, explanation: 'A ton of fish costs V 0.5 computers but costs W 1 computer, so V has the comparative advantage in fish. V gives up 2 tons of fish per computer versus 1 ton for W, so W has the advantage in computers, and V (100 tons versus 80) holds the absolute advantage in fish.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  { question: 'Before trade, V made 50 tons of fish and 25 computers and W made 40 tons of fish and 40 computers. After V specializes in fish (100 tons) and W in computers (80), how much does combined output rise?', options: ['20 tons of fish and 30 computers', '10 tons of fish and 15 computers', '10 tons of fish and no computers', '0 tons of fish and 15 computers'], correctAnswer: 1, explanation: 'Combined output rises from 90 to 100 tons of fish and from 65 to 80 computers, a gain of 10 tons and 15 computers. Doubling those figures overstates the gain, and claiming no gain in one good overlooks that specialization raised output of both.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'Japan has a comparative advantage in cameras and Chile has a comparative advantage in copper. Under free trade between them, Japan is expected to', options: ['export copper and import cameras', 'import both cameras and copper', 'export cameras and import copper', 'export both cameras and copper'], correctAnswer: 2, explanation: 'Each country exports the good it produces at the lower opportunity cost and imports the other, so Japan exports cameras and imports copper. Reversing the flows ignores comparative advantage, and no country can be the low-cost producer of every good.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  { question: 'Country A\'s opportunity cost of 1 tablet is 5 bags of rice; Country B\'s is 2 bags. B proposes trading tablets at 1 tablet for 6 bags of rice. What is the expected outcome?', options: ['A refuses, since it can make a tablet for 5 bags', 'B refuses, since it gives up too much rice', 'Both gain, since the price exceeds both costs', 'Both gain, since B has the lower cost of tablets'], correctAnswer: 0, explanation: 'At 6 bags per tablet, A would pay more than the 5 bags it gives up making a tablet itself, so A will not buy. B would happily receive 6 bags for something costing it 2, and terms above both costs fall outside the 2-to-5 range that benefits both.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 2, part: 1 },
  { question: 'Why does specialization according to comparative advantage raise total world output?', options: ['Goods are made where the most workers are available', 'Goods are made where output per worker is highest', 'Countries produce more of both goods than before trade', 'Goods are made where the least is given up to make them'], correctAnswer: 3, explanation: 'When each good is made by the producer with the lowest opportunity cost, the same resources yield more total output. Worker counts and output per worker describe size and absolute advantage, and each specializing country produces more of one good but less of the other.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'macro-comparative-advantage', formSet: 1, part: 1 },
  // ── Domain: measurement · macro-gdp-growth ───────────────────────────
  { question: 'Which purchase is counted in the investment (I) component of U.S. GDP?', options: ['A family buys a newly built house', 'A family buys 100 shares of stock', 'A family buys a new refrigerator', 'A family buys a 2015 used car'], correctAnswer: 0, explanation: 'New residential construction is counted as investment in GDP. Buying stock is a financial transaction rather than production, a new refrigerator is consumption, and a used car was counted in the year it was made.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'Which transaction is excluded from this year\'s U.S. GDP?', options: ['A city pays a contractor to repave a road', 'A retiree receives a Social Security payment', 'A tourist from Spain pays for a hotel in Ohio', 'A firm adds unsold sweaters to its inventory'], correctAnswer: 1, explanation: 'Social Security is a transfer payment that redistributes income without paying for new production, so it is excluded. Road repaving is a government purchase, a foreign tourist\'s hotel stay is a U.S. export, and additions to inventory count as investment.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'An economy reports consumption of \\$600 billion, investment of \\$150 billion, government purchases of \\$200 billion, exports of \\$80 billion, imports of \\$110 billion, and transfer payments of \\$90 billion. What is GDP?', options: ['\\$920 billion', '\\$980 billion', '\\$1,010 billion', '\\$1,030 billion'], correctAnswer: 0, explanation: 'GDP = C + I + G + (X − M) = 600 + 150 + 200 + (80 − 110) = \\$920 billion. Transfer payments are excluded, so adding them is an error, and treating net exports as +\\$30 billion or counting only exports overstates GDP.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'A country\'s nominal GDP is \\$30 trillion and its GDP deflator is 125. What is its real GDP?', options: ['\\$37.5 trillion', '\\$22.5 trillion', '\\$24 trillion', '\\$30 trillion'], correctAnswer: 2, explanation: 'Real GDP = (nominal GDP ÷ deflator) × 100 = (30 ÷ 125) × 100 = \\$24 trillion. Multiplying by 1.25 inflates rather than deflates, subtracting 25% of nominal GDP is not the same as dividing by 1.25, and \\$30 trillion ignores the price change.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'Nominal GDP is \\$18 trillion and real GDP is \\$15 trillion. What is the GDP deflator?', options: ['20', '83', '120', '300'], correctAnswer: 2, explanation: 'Deflator = (nominal GDP ÷ real GDP) × 100 = (18 ÷ 15) × 100 = 120. A value of 83 inverts the ratio, 20 is the percentage gap rather than the index, and 300 multiplies the difference by 100.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'Between two years, a country\'s nominal GDP rises by 6% and its GDP deflator also rises by 6%. Which conclusion is best supported?', options: ['Real output grew by about 6%', 'Real output grew by about 12%', 'Real output fell by about 6%', 'Real output barely changed'], correctAnswer: 3, explanation: 'Real GDP growth is roughly nominal growth minus inflation, 6% − 6% ≈ 0, so actual output was about the same. Six percent mistakes price increases for more output, 12% adds inflation instead of removing it, and a 6% fall subtracts the price change twice.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'A Korean-owned electronics plant operates in Texas. Its output is counted in', options: ['Korea\'s GDP, since a Korean firm owns it', 'Both countries\' GDP, split by ownership', 'U.S. GDP, since it is made on U.S. soil', 'Neither country\'s GDP, as it is foreign'], correctAnswer: 2, explanation: 'GDP counts production within a country\'s borders, whoever owns the firm, so the plant\'s output is in U.S. GDP only. Ownership does not move the output into Korea\'s GDP or split it, and production on U.S. soil is never left out of GDP.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'A lumber mill sells \\$200 of wood to a furniture maker, which uses it to build a table that a consumer buys for \\$700. How much do these transactions add to GDP?', options: ['\\$500', '\\$700', '\\$900', '\\$1,400'], correctAnswer: 1, explanation: 'Only the final good counts, so GDP rises by the table\'s \\$700 price, which already includes the wood. Adding the wood again (\\$900) double-counts an intermediate good, and \\$500 is just the furniture maker\'s value added.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'A firm produces 1,000 jackets this year but sells only 800; the other 200 go into inventory. How are the unsold jackets treated in this year\'s GDP?', options: ['They are excluded until they sell', 'They count as consumption this year', 'They count as investment this year', 'They count as next year\'s output'], correctAnswer: 2, explanation: 'GDP measures production, and goods added to inventory are recorded as investment in the year they are made. They are not consumption because no household bought them, and counting them later would attribute this year\'s production to the wrong year.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'A news report says a country\'s nominal GDP doubled over 20 years. Before concluding that the typical resident\'s living standard improved, an economist would most want to know', options: ['how much the price level and population changed', 'how much of GDP came from government spending', 'whether net exports were positive or negative', 'how much the stock market rose over the period'], correctAnswer: 0, explanation: 'Doubling nominal GDP could reflect rising prices or a growing population, so the meaningful measure is real GDP per person. The mix of spending, the trade balance, and stock prices do not tell you whether output per person actually grew.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'Which of the following is counted as government spending (G) in GDP?', options: ['Unemployment benefits paid to laid-off workers', 'Social Security checks mailed to retirees', 'Food assistance benefits paid to low-income families', 'Salaries paid to public school teachers'], correctAnswer: 3, explanation: 'Teacher salaries buy a service (education), so they are a government purchase. Unemployment benefits, Social Security, and food assistance are transfer payments that move income without buying any newly produced good or service.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'This year a country exports \\$300 billion of goods and services and imports \\$420 billion. In the expenditure approach, net exports equal', options: ['\\$120 billion', '−\\$120 billion', '−\\$420 billion', '\\$720 billion'], correctAnswer: 1, explanation: 'Net exports are exports minus imports: 300 − 420 = −\\$120 billion, a trade deficit that lowers measured GDP. A positive \\$120 billion reverses the subtraction, −\\$420 billion ignores exports, and \\$720 billion adds the two flows.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'In the expenditure approach (GDP = C + I + G + Xn), why are imports subtracted?', options: ['Imports shrink the number of domestic jobs', 'Import purchases already appear in spending totals', 'Imports are paid for with borrowed funds', 'Imports carry tariffs collected at the border'], correctAnswer: 1, explanation: 'When households, firms, or government buy foreign goods, that spending is already recorded in C, I, or G, so it must be subtracted to leave only domestic production. Job effects, how imports are financed, and tariffs have nothing to do with the accounting identity.', difficulty: 'hard', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'In Year 1, nominal GDP is \\$500 billion and the GDP deflator is 100. In Year 2, nominal GDP is \\$594 billion and the deflator is 110. By how much did real GDP grow?', options: ['8%', '8.8%', '10%', '18.8%'], correctAnswer: 0, explanation: 'Year 2 real GDP is 594 ÷ 1.10 = \\$540 billion, which is 8% above \\$500 billion. The 18.8% figure is nominal growth, 10% is the rise in the price level, and 8.8% comes from subtracting 10 from 18.8, which is only an approximation.', difficulty: 'hard', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'A country\'s real GDP grows by 3% in a year while its population grows by 1%. Real GDP per capita grows by about', options: ['3%', '4%', '1%', '2%'], correctAnswer: 3, explanation: 'Growth in output per person is approximately output growth minus population growth: 3% − 1% = 2%. Three percent ignores population growth, 4% adds it, and 1% is the population growth rate itself.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  { question: 'Which change would raise measured GDP even though the total amount of goods and services actually produced stays the same?', options: ['A worker takes a second job and works more hours each week', 'A household sells its used car to a neighbor', 'A parent stops home childcare and pays a daycare instead', 'A family buys government bonds with its savings'], correctAnswer: 2, explanation: 'Childcare done at home is a nonmarket activity that GDP misses; when the same care is bought from a daycare, it becomes a market transaction and is counted. A second job adds real production, while a used-car sale and a bond purchase are not new production and leave GDP unchanged.', difficulty: 'hard', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 2, part: 1 },
  { question: 'GDP is the market value of all ______ produced within a country\'s borders in a given period.', options: ['intermediate goods and services', 'final goods and services', 'goods and services sold', 'goods made by its citizens'], correctAnswer: 1, explanation: 'GDP counts final goods and services so that intermediate inputs are not double-counted. It includes goods produced but not yet sold (as inventory investment), and it is based on location, not the citizenship of the producer.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-gdp-growth', formSet: 1, part: 1 },
  // ── Domain: measurement · macro-unemployment-inflation ───────────────
  { question: 'A travel agent loses her job because most customers now book trips online, and her skills are no longer in demand. She is experiencing', options: ['frictional unemployment', 'structural unemployment', 'cyclical unemployment', 'seasonal unemployment'], correctAnswer: 1, explanation: 'A lasting mismatch between a worker\'s skills and available jobs, caused here by technology, is structural unemployment. Frictional unemployment is a short search between suitable jobs, cyclical unemployment comes from a recession, and seasonal unemployment follows the calendar.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'During a recession, a furniture company lays off 300 workers because orders from stores have collapsed. These workers are experiencing', options: ['seasonal unemployment', 'frictional unemployment', 'structural unemployment', 'cyclical unemployment'], correctAnswer: 3, explanation: 'Job losses caused by a drop in aggregate demand during a downturn are cyclical unemployment. The workers\' skills are still useful once demand recovers, so it is not structural, and the layoffs are neither voluntary job searching nor tied to the season.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'A nurse quits her hospital job and spends six weeks interviewing for a better-paying position. During the search she is', options: ['frictionally unemployed', 'structurally unemployed', 'cyclically unemployed', 'not in the labor force'], correctAnswer: 0, explanation: 'Time spent searching between jobs while one\'s skills remain in demand is frictional unemployment. Her skills match many openings, so it is not structural; no recession caused it, so it is not cyclical; and because she is actively looking, she is in the labor force.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'A country has 150 million employed people, 10 million unemployed people who are actively seeking work, and 40 million adults not in the labor force. The unemployment rate is', options: ['5.0%', '6.25%', '6.7%', '25%'], correctAnswer: 1, explanation: 'The labor force is 150 + 10 = 160 million, so the rate is 10 ÷ 160 = 6.25%. Dividing by the whole adult population gives 5.0%, dividing by employment alone gives 6.7%, and 25% mistakes the people outside the labor force for unemployed.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'Using the same data (150 million employed, 10 million unemployed, 40 million adults not in the labor force), what is the labor force participation rate?', options: ['75%', '93.75%', '20%', '80%'], correctAnswer: 3, explanation: 'Participation = labor force ÷ adult population = 160 ÷ 200 = 80%. Seventy-five percent counts only the employed, 93.75% is the employed share of the labor force, and 20% is the share outside the labor force.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'Several thousand unemployed workers become discouraged and stop looking for work. Holding everything else constant, the measured unemployment rate', options: ['rises, because more people lack jobs', 'is unchanged, because they still lack jobs', 'falls, because they leave the labor force', 'rises, because the labor force shrinks'], correctAnswer: 2, explanation: 'Discouraged workers are no longer counted as unemployed or in the labor force; removing the same number from both the numerator and the larger denominator lowers the rate. The number of people without jobs did not grow, and a smaller labor force here lowers rather than raises the rate.', difficulty: 'hard', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'An economy is at full employment, with a natural rate of unemployment of 4.5%. Which statement must be true?', options: ['Cyclical unemployment is zero', 'Frictional unemployment is zero', 'Structural unemployment is zero', 'Every job seeker is currently employed'], correctAnswer: 0, explanation: 'The natural rate is frictional plus structural unemployment, so full employment means only cyclical unemployment has disappeared. Frictional and structural unemployment are still present, which is why measured unemployment stays at 4.5% rather than zero.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'Unemployment is currently 7%: 2% frictional, 2.5% structural, and 2.5% cyclical. What is the natural rate of unemployment?', options: ['2.5%', '4.5%', '5%', '7%'], correctAnswer: 1, explanation: 'The natural rate is frictional plus structural unemployment: 2% + 2.5% = 4.5%. The 7% figure includes cyclical unemployment, 5% wrongly adds structural and cyclical, and 2.5% is a single component.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'The consumer price index rises from 160 to 168 over one year. What is the inflation rate?', options: ['8%', '4.8%', '5%', '0.5%'], correctAnswer: 2, explanation: 'Inflation = (168 − 160) ÷ 160 × 100 = 5%. Eight percent is the point change mistaken for a percent, 4.8% divides by the new index instead of the old one, and 0.5% misplaces the decimal.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'A market basket costs \\$400 in the base year and \\$460 in the current year. What is the current-year CPI?', options: ['115', '15', '87', '60'], correctAnswer: 0, explanation: 'CPI = (current cost ÷ base cost) × 100 = (460 ÷ 400) × 100 = 115. Fifteen is the inflation rate since the base year rather than the index, 87 inverts the ratio, and 60 is the dollar change.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'A bank makes a one-year loan at a 7% nominal interest rate, and inflation over the year turns out to be 4%. What real interest rate does the bank earn?', options: ['11%', '3%', '4%', '7%'], correctAnswer: 1, explanation: 'The real interest rate is approximately the nominal rate minus inflation: 7% − 4% = 3%. Eleven percent adds inflation instead of subtracting it, 7% is the nominal rate, and 4% is the inflation rate.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'Two parties sign a fixed-rate loan contract expecting 2% inflation, but inflation turns out to be 6%. Who is helped by the unexpected inflation?', options: ['The lender, who receives more dollars than expected', 'Neither, because the loan rate was fixed in advance', 'The borrower, who repays with less valuable dollars', 'Both, because their incomes rise with prices'], correctAnswer: 2, explanation: 'Unexpected inflation lowers the real value of the fixed repayments, so the borrower gains at the lender\'s expense. The lender receives exactly the agreed number of dollars, each worth less, and the fixed rate is precisely why the surprise shifts wealth between them.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'Which person is most likely to be hurt by an unexpected rise in inflation?', options: ['A homeowner repaying a fixed-rate mortgage', 'A worker whose wage contract includes a COLA', 'A government with a large outstanding debt', 'A retiree on a pension with no COLA'], correctAnswer: 3, explanation: 'A fixed pension buys less as prices rise, so the retiree loses purchasing power. Fixed-rate borrowers such as the homeowner and the indebted government gain, and a COLA raises the worker\'s wage along with prices.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'A sharp rise in global oil prices pushes up production costs across the economy, and the price level rises. In the AD-AS model, this is best described as', options: ['A rightward AD shift, or demand-pull inflation', 'A leftward AD shift, or cost-push inflation', 'A leftward SRAS shift, or cost-push inflation', 'A rightward SRAS shift, or demand-pull inflation'], correctAnswer: 2, explanation: 'Higher input costs reduce short-run aggregate supply, and the resulting price increase is cost-push inflation. Demand-pull inflation comes from AD shifting right, a leftward AD shift lowers the price level, and SRAS shifting right would lower prices too.', difficulty: 'medium', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'With the economy already near full employment, a stock market boom leads households to spend much more, and the price level climbs. This is best described as', options: ['cost-push inflation caused by rising input prices', 'demand-pull inflation caused by rising purchases', 'cost-push inflation caused by higher wage demands', 'deflation caused by falling consumer confidence'], correctAnswer: 1, explanation: 'Spending growing faster than the economy can produce pulls the price level up, which is demand-pull inflation from AD shifting right. Cost-push inflation starts with higher production costs, and deflation is a falling price level, not a rising one.', difficulty: 'easy', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  { question: 'Critics argue that the CPI overstates the true rise in the cost of living. Which reason supports this claim?', options: ['Shoppers substitute toward goods whose prices rose less', 'The basket weights imports more heavily than households do', 'The index leaves out price changes for services such as rent', 'The index follows prices paid by government, not households'], correctAnswer: 0, explanation: 'Because the basket is fixed, the CPI misses that households substitute toward goods whose prices rose less, so it overstates their true cost increase. The CPI does include services such as rent and tracks consumer rather than government purchases, and its weights come from household spending, so import weighting is not the standard source of upward bias.', difficulty: 'hard', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 2, part: 1 },
  { question: 'A worker\'s nominal wage rises by 3% in a year in which the CPI rises by 5%. Her real wage', options: ['rises by about 3%', 'rises by about 8%', 'rises by about 2%', 'falls by about 2%'], correctAnswer: 3, explanation: 'Real wage growth is roughly nominal wage growth minus inflation: 3% − 5% = −2%, so her purchasing power falls. Three percent ignores inflation, 8% adds it, and a 2% rise gets the sign backward.', difficulty: 'hard', domain: 'measurement', topicSlug: 'macro-unemployment-inflation', formSet: 1, part: 1 },
  // ── Domain: national-income · macro-ad-as ────────────────────────────
  { question: 'Which event would shift the aggregate demand curve to the left?', options: ['The central bank lowers interest rates', 'Households grow pessimistic about income', 'Foreign incomes rise, boosting U.S. exports', 'Firms become optimistic about future sales'], correctAnswer: 1, explanation: 'Pessimistic households cut consumption at every price level, shifting AD left. Lower interest rates, stronger foreign demand for exports, and business optimism all raise spending and shift AD to the right.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'The overall price level in an economy falls. In the AD-AS model, this causes', options: ['a movement down along the AD curve', 'a rightward shift of the AD curve', 'a leftward shift of the AD curve', 'a rightward shift of the LRAS curve'], correctAnswer: 0, explanation: 'A change in the price level moves the economy along the existing AD curve to a larger quantity of real output demanded. AD shifts only when spending changes at every price level, and LRAS depends on resources and technology, not prices.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'When the price level rises, the purchasing power of households\' savings falls, so they buy less output. This reason for the downward slope of aggregate demand is the', options: ['interest rate effect', 'net export effect', 'wealth effect', 'crowding-out effect'], correctAnswer: 2, explanation: 'A drop in the real value of savings that reduces consumption is the wealth (real-balances) effect. The interest rate effect works through borrowing costs, the net export effect through relative prices across countries, and crowding out describes government borrowing raising interest rates.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'A higher price level raises the demand for money, which pushes up interest rates and reduces investment spending. This chain of reasoning explains', options: ['why SRAS slopes upward', 'why LRAS is vertical', 'why AD shifts to the left', 'why AD slopes downward'], correctAnswer: 3, explanation: 'This is the interest rate effect, one of the three reasons the AD curve slopes downward. Because the change starts with the price level, it is a movement along AD rather than a shift, and it says nothing about the slope of SRAS or LRAS.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'Which event would shift the short-run aggregate supply curve to the right?', options: ['An increase in nominal wages across industries', 'A new per-unit tax on business inputs', 'A drop in the price of oil and other energy', 'A rise in the overall price level'], correctAnswer: 2, explanation: 'Cheaper energy lowers production costs, so firms supply more at every price level. Higher wages and new input taxes raise costs and shift SRAS left, and a change in the price level is a movement along SRAS, not a shift.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'A drought destroys much of a nation\'s harvest, raising input costs throughout the economy. In the short run, how do the price level and real output change?', options: ['Price level falls; real output rises', 'Price level rises; real output rises', 'Price level falls; real output falls', 'Price level rises; real output falls'], correctAnswer: 3, explanation: 'Higher input costs shift SRAS left, moving the economy up along AD to a higher price level and lower output. Rising output with rising prices would require AD to increase, and a lower price level with lower output would come from AD falling.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'An economy starts in long-run equilibrium when consumer confidence surges. In the short run, compared with the starting point,', options: ['Price level rises; real output falls', 'Price level rises; real output rises', 'Price level falls; real output rises', 'Price level is unchanged; real output rises'], correctAnswer: 1, explanation: 'Higher confidence shifts AD right along an upward-sloping SRAS, so both the price level and real output rise. Rising prices with falling output describes an SRAS decrease, and the price level cannot fall or stay put when AD rises along an upward-sloping SRAS.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'Real GDP is \\$18 trillion while full-employment (potential) GDP is \\$20 trillion. Which describes this economy?', options: ['a recessionary gap, and unemployment is above the natural rate', 'an inflationary gap, and unemployment is above the natural rate', 'a recessionary gap, and unemployment is below the natural rate', 'an inflationary gap, and unemployment is below the natural rate'], correctAnswer: 0, explanation: 'Output below potential is a recessionary gap, and producing less than potential leaves cyclical unemployment, so unemployment exceeds the natural rate. An inflationary gap requires output above potential, and below-natural unemployment occurs only then.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'An economy is in a recessionary gap and policymakers take no action. According to the AD-AS model, what happens in the long run?', options: ['nominal wages rise, SRAS shifts left, and output returns to potential', 'nominal wages fall, AD shifts right, and output returns to potential', 'LRAS shifts left until it meets the current, lower level of output', 'nominal wages fall, SRAS shifts right, and output returns to potential'], correctAnswer: 3, explanation: 'High unemployment eventually pushes nominal wages and other input prices down, shifting SRAS right until output returns to potential at a lower price level. Rising wages would deepen the gap, falling wages affect costs (SRAS) rather than spending (AD), and potential output does not shrink to match a temporary slump.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'An economy is in an inflationary gap and policymakers take no action. The long-run adjustment results in', options: ['a lower price level and output back at potential', 'a higher price level and output back at potential', 'a higher price level and output above potential', 'the same price level and output below potential'], correctAnswer: 1, explanation: 'Tight labor markets push nominal wages up, shifting SRAS left until output falls back to potential at an even higher price level. The price level does not fall during this adjustment, and output cannot stay above potential once wages adjust.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'Why is the long-run aggregate supply curve vertical?', options: ['Long-run output depends on resources, not prices', 'Long-run prices are fixed by the central bank', 'Long-run nominal wages never adjust to prices', 'Long-run AD stays fixed at full-employment output'], correctAnswer: 0, explanation: 'In the long run, wages and prices fully adjust, so potential output is set by resources and technology regardless of the price level. Central banks do not fix the price level, wages adjust fully in the long run, and AD can still shift.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'Which event shifts the long-run aggregate supply curve to the right?', options: ['An increase in consumer spending', 'A decrease in the price level', 'A larger capital stock', 'A temporary fall in oil prices'], correctAnswer: 2, explanation: 'More capital raises the economy\'s productive capacity, increasing potential output. Consumer spending shifts AD, a price-level change is a movement along the curves, and a temporary fall in input prices shifts only SRAS.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'In the same period, aggregate demand shifts right and short-run aggregate supply shifts left. Compared with the original equilibrium, what can be determined?', options: ['Output rises; the change in the price level is uncertain', 'The price level rises; the change in output is uncertain', 'The price level falls; the change in output is uncertain', 'The price level and output both rise'], correctAnswer: 1, explanation: 'Both shifts push the price level up, so it definitely rises; the AD increase raises output while the SRAS decrease lowers it, so the net change in output depends on the sizes of the shifts. The price level cannot fall, and neither output nor both variables can be known to rise without knowing magnitudes.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'The U.S. price level rises while price levels abroad stay the same. Through the net export effect, the quantity of U.S. real output demanded', options: ['rises, because U.S. firms earn more per export', 'falls, because the dollar loses value abroad', 'rises, because imports become relatively more expensive', 'falls, as U.S. goods become pricier'], correctAnswer: 3, explanation: 'A higher U.S. price level makes U.S. goods more expensive relative to foreign goods, so exports fall and imports rise, reducing net exports. Imports become relatively cheaper, not more expensive, and the effect works through relative goods prices rather than a change in the exchange rate.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'The central bank increases the money supply, lowering interest rates. In the AD-AS model, the main short-run effect is that', options: ['AD shifts right as borrowing rises', 'SRAS shifts right as borrowing costs fall', 'LRAS shifts right as capital becomes cheaper', 'AD shifts left as savers earn less interest'], correctAnswer: 0, explanation: 'Lower interest rates encourage borrowing for investment and big-ticket consumption, shifting AD to the right. Monetary policy works mainly through spending rather than production costs, so SRAS and LRAS are not the main channel, and lower saving returns do not reduce total spending.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  { question: 'Government spending falls sharply while the economy is at full employment. In the short run, the economy moves to', options: ['an inflationary gap with a higher price level', 'a recessionary gap with a higher price level', 'a recessionary gap with a lower price level', 'long-run equilibrium at a lower price level'], correctAnswer: 2, explanation: 'Lower government spending shifts AD left, reducing both output and the price level, so output falls below potential: a recessionary gap. An inflationary gap needs AD to rise, a higher price level contradicts an AD decrease, and the economy is not in long-run equilibrium while output is below potential.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 2, part: 1 },
  { question: 'Over one year, the price level rises from 110 to 118 while real GDP falls from \\$20 trillion to \\$19.4 trillion. This combination is most consistent with', options: ['demand-pull inflation from AD shifting right', 'a recession from AD shifting left', 'growth from LRAS shifting right', 'stagflation from SRAS shifting left'], correctAnswer: 3, explanation: 'A rising price level together with falling output is stagflation, the signature of SRAS shifting left. An AD increase would raise output, an AD decrease would lower the price level, and LRAS growth would raise output.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-ad-as', formSet: 1, part: 1 },
  // ── Domain: national-income · macro-multiplier-effect ────────────────
  { question: 'Households spend \\$90 of every additional \\$100 of disposable income they receive. What is the marginal propensity to save?', options: ['0.9', '10', '0.1', '9'], correctAnswer: 2, explanation: 'The MPS is the share of extra income saved: \\$10 ÷ \\$100 = 0.1. The value 0.9 is the MPC, 10 is the spending multiplier (1 ÷ 0.1), and 9 is the tax multiplier in absolute value.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'If the marginal propensity to consume is 0.6, the simple spending multiplier is', options: ['1.67', '2.5', '0.4', '1.5'], correctAnswer: 1, explanation: 'Spending multiplier = 1 ÷ (1 − MPC) = 1 ÷ 0.4 = 2.5. The value 1.67 divides by the MPC instead of the MPS, 0.4 is the MPS itself, and 1.5 is the tax multiplier (0.6 ÷ 0.4) in absolute value.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'The MPC is 0.75 and business investment rises by \\$40 billion. What is the maximum resulting change in real GDP?', options: ['\\$160 billion', '\\$40 billion', '\\$53 billion', '\\$30 billion'], correctAnswer: 0, explanation: 'The spending multiplier is 1 ÷ 0.25 = 4, so GDP can rise by 4 × \\$40 billion = \\$160 billion. The \\$40 billion figure ignores the rounds of re-spending entirely, \\$53 billion divides by the MPC, and \\$30 billion counts only the first round of re-spending.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'The MPC is 0.9 and the government cuts taxes by \\$20 billion. What is the maximum resulting change in real GDP?', options: ['\\$200 billion increase', '\\$18 billion increase', '\\$180 billion decrease', '\\$180 billion increase'], correctAnswer: 3, explanation: 'The tax multiplier is −MPC ÷ MPS = −0.9 ÷ 0.1 = −9, so a \\$20 billion cut raises GDP by up to \\$180 billion. Using the spending multiplier of 10 overstates the effect, \\$18 billion is only the first round of spending, and a tax cut raises rather than lowers GDP.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'An economy faces a recessionary gap of \\$240 billion and the MPC is 0.8. What increase in government spending would close the gap?', options: ['\\$192 billion', '\\$48 billion', '\\$1,200 billion', '\\$240 billion'], correctAnswer: 1, explanation: 'The spending multiplier is 1 ÷ 0.2 = 5, so the required increase is \\$240 billion ÷ 5 = \\$48 billion. The \\$192 billion figure multiplies the gap by the MPC, \\$240 billion ignores the multiplier, and \\$1,200 billion multiplies the gap instead of dividing it.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'An economy faces a recessionary gap of \\$240 billion and the MPC is 0.8. Using only a change in taxes, the government should', options: ['Cut taxes by \\$48 billion', 'Cut taxes by \\$240 billion', 'Cut taxes by \\$60 billion', 'Raise taxes by \\$60 billion'], correctAnswer: 2, explanation: 'The tax multiplier is 0.8 ÷ 0.2 = 4 in absolute value, so a tax cut of \\$240 billion ÷ 4 = \\$60 billion closes the gap. A \\$48 billion cut uses the spending multiplier and falls short, a \\$240 billion cut ignores the multiplier, and raising taxes would widen a recessionary gap.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'Real GDP exceeds potential GDP by \\$100 billion and the MPC is 0.5. To close the gap using government spending alone, the government should', options: ['decrease spending by \\$50 billion', 'increase spending by \\$50 billion', 'decrease spending by \\$100 billion', 'decrease spending by \\$200 billion'], correctAnswer: 0, explanation: 'Output above potential is an inflationary gap, so spending must fall; with a multiplier of 1 ÷ 0.5 = 2, a \\$50 billion cut reduces GDP by \\$100 billion. Increasing spending would widen the gap, a \\$100 billion cut ignores the multiplier, and \\$200 billion multiplies instead of dividing.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'Congress is choosing between \\$50 billion of new highway spending and a \\$50 billion tax cut. With an MPC of 0.8, the highway plan raises GDP by more because', options: ['tax cuts are reduced by crowding out but spending is not', 'government spending raises the marginal propensity to consume', 'tax cuts are paid back out of future government spending', 'households save part of a tax cut before spending the rest'], correctAnswer: 3, explanation: 'All \\$50 billion of new spending enters the income stream at once, while households save 20% of a tax cut before the first round, so GDP rises by \\$250 billion versus \\$200 billion. Crowding out can affect both policies, government purchases do not change households\' MPC, and nothing requires a tax cut to be offset by later spending.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'If the marginal propensity to save is 0.25, what is the marginal propensity to consume?', options: ['0.75', '4', '1.25', '0.25'], correctAnswer: 0, explanation: 'The MPC and MPS always sum to 1, so MPC = 1 − 0.25 = 0.75. Four is the spending multiplier, 1.25 adds instead of subtracting, and 0.25 repeats the MPS.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'Which change would increase the size of the simple spending multiplier?', options: ['An increase in the MPS', 'An increase in the MPC', 'An increase in government spending', 'An increase in the interest rate'], correctAnswer: 1, explanation: 'The multiplier equals 1 ÷ (1 − MPC), so a higher MPC means more of each round is re-spent and the multiplier grows. A higher MPS shrinks it, and the level of government spending or interest rates changes how much spending is multiplied, not the multiplier itself.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'A firm spends \\$1,000 on new equipment, and the MPC is 0.6. The equipment maker\'s workers and owners receive the \\$1,000 as income. How much of it do they spend in the next round?', options: ['\\$400', '\\$360', '\\$600', '\\$1,600'], correctAnswer: 2, explanation: 'Recipients spend the MPC share of new income: 0.6 × \\$1,000 = \\$600. Four hundred dollars is the amount saved, \\$360 is the round after that (0.6 × \\$600), and \\$1,600 is the running total of the first two rounds.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'With an MPC of 0.6, what is the maximum total increase in GDP from a \\$1,000 increase in investment spending?', options: ['\\$1,600', '\\$1,667', '\\$6,000', '\\$2,500'], correctAnswer: 3, explanation: 'The multiplier is 1 ÷ 0.4 = 2.5, so total GDP rises by up to 2.5 × \\$1,000 = \\$2,500. Sixteen hundred dollars stops after one round of re-spending, \\$1,667 divides by the MPC, and \\$6,000 is not produced by any multiplier formula.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'Foreign demand for a country\'s exports rises by \\$20 billion and the MPS is 0.2. What is the maximum resulting change in real GDP?', options: ['\\$80 billion', '\\$25 billion', '\\$4 billion', '\\$100 billion'], correctAnswer: 3, explanation: 'Exports are a component of spending, so the spending multiplier of 1 ÷ 0.2 = 5 applies: 5 × \\$20 billion = \\$100 billion. Eighty billion wrongly uses the tax multiplier, \\$25 billion divides by the MPC, and \\$4 billion multiplies by the MPS.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'The MPC is 0.75 and the government raises taxes by \\$40 billion. What is the maximum resulting change in real GDP?', options: ['−\\$160 billion', '+\\$120 billion', '−\\$120 billion', '−\\$30 billion'], correctAnswer: 2, explanation: 'The tax multiplier is −0.75 ÷ 0.25 = −3, so GDP falls by up to 3 × \\$40 billion = \\$120 billion. A \\$160 billion drop uses the spending multiplier, a tax increase cannot raise GDP, and \\$30 billion counts only the first-round cut in consumption.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'An increase in investment of \\$25 billion ultimately raises real GDP by \\$100 billion. What is the MPC?', options: ['0.25', '0.75', '0.8', '4'], correctAnswer: 1, explanation: 'The multiplier is \\$100 billion ÷ \\$25 billion = 4, and 4 = 1 ÷ (1 − MPC) gives MPC = 0.75. The value 0.25 is the MPS, 4 is the multiplier rather than the MPC, and 0.8 would imply a multiplier of 5.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  { question: 'Which statement best explains why an initial increase in spending raises GDP by a multiple of that increase?', options: ['Purchases become income that is partly spent again', 'Prices rise in each round, so nominal output keeps growing', 'Banks lend out each new deposit several times over', 'Firms build up inventory in anticipation of more sales'], correctAnswer: 0, explanation: 'Each dollar spent is income to someone else, who spends the MPC share of it, creating successive rounds of new spending. The spending multiplier measures real output, not price increases; repeated bank lending describes the money multiplier; and inventory buildup is not the mechanism.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 2, part: 1 },
  { question: 'If the MPC rises from 0.8 to 0.9, the simple spending multiplier', options: ['rises slightly, from 5 to 5.5', 'falls, from 5 to 4', 'is unchanged at 5', 'doubles, from 5 to 10'], correctAnswer: 3, explanation: 'The multiplier moves from 1 ÷ 0.2 = 5 to 1 ÷ 0.1 = 10, so it doubles. Because the MPS is in the denominator, halving it doubles the multiplier rather than raising it slightly, and a higher MPC can never shrink or leave the multiplier unchanged.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-multiplier-effect', formSet: 1, part: 1 },
  // ── Domain: national-income · macro-phillips-curve ───────────────────
  { question: 'Government spending rises sharply while the economy is near full employment. On the short-run Phillips curve, the economy', options: ['moves down and to the right along the curve', 'moves up and to the left along the curve', 'shifts the curve to the right', 'shifts the curve to the left'], correctAnswer: 1, explanation: 'Higher spending shifts AD right, raising inflation and lowering unemployment, which is a movement up and to the left along the existing SRPC. Moving down and to the right reflects falling AD, and the SRPC itself shifts only with supply shocks or changes in expected inflation.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'A sudden surge in energy prices hits the economy. In the Phillips curve model, this is shown as', options: ['a leftward shift of the SRPC', 'a movement up along the SRPC', 'a rightward shift of the SRPC', 'a rightward shift of the LRPC'], correctAnswer: 2, explanation: 'A negative supply shock worsens the trade-off, raising inflation at every unemployment rate, so the SRPC shifts right (up). A movement along the SRPC comes from AD changes, a leftward shift reflects a favorable shock, and the LRPC moves only if the natural rate changes.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'Workers and firms come to expect higher inflation next year and build it into wage and price contracts. The short-run Phillips curve', options: ['shifts to the right', 'shifts to the left, toward the origin', 'stays put as the economy moves up it', 'becomes vertical at the natural rate'], correctAnswer: 0, explanation: 'Higher expected inflation raises the inflation rate associated with every unemployment rate, shifting the SRPC up and to the right. A leftward shift follows lower expectations, a movement along the curve comes from AD changes, and only the long-run curve is vertical.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'In the long run, the Phillips curve is vertical at', options: ['zero percent unemployment', 'the target inflation rate', 'the current unemployment rate', 'the natural rate of unemployment'], correctAnswer: 3, explanation: 'Once expectations adjust, unemployment returns to its natural rate whatever the inflation rate, so the LRPC is vertical there. Some frictional and structural unemployment always remains, so it is not zero, and the curve is vertical in unemployment, not set by an inflation target or the current rate.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'An economy has unemployment of 8% while its natural rate is 5%. On a Phillips curve graph, the economy is at a point', options: ['on the SRPC to the right of the LRPC', 'on the SRPC to the left of the LRPC', 'on the LRPC above the SRPC', 'where the SRPC crosses the LRPC'], correctAnswer: 0, explanation: 'Unemployment above the natural rate places the economy on its SRPC to the right of the vertical LRPC, which corresponds to a recessionary gap. Points to the left of the LRPC have unemployment below the natural rate, and the intersection is long-run equilibrium at 5%.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'Policymakers use expansionary policy to hold unemployment below the natural rate. Once inflation expectations fully adjust, what is the outcome?', options: ['Inflation is higher; unemployment stays below the natural rate', 'Inflation is higher; unemployment returns to the natural rate', 'Inflation is lower; unemployment returns to the natural rate', 'Inflation is unchanged; unemployment rises above the natural rate'], correctAnswer: 1, explanation: 'Workers build the higher inflation into wage demands, the SRPC shifts up, and unemployment drifts back to the natural rate at a higher inflation rate. Unemployment cannot stay below the natural rate once expectations catch up, and the episode raises rather than lowers inflation.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'A rightward shift of the short-run Phillips curve means', options: ['lower inflation at every unemployment rate', 'a movement toward lower unemployment', 'a shift of the LRPC to the left', 'higher inflation at every unemployment rate'], correctAnswer: 3, explanation: 'Shifting the SRPC right (up) means each unemployment rate now comes with higher inflation, a worse trade-off. Lower inflation at each unemployment rate is a leftward shift, a movement toward lower unemployment happens along the curve, and the LRPC is unaffected.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'The central bank sharply raises interest rates, reducing aggregate demand. In the short run, the economy moves', options: ['up and to the left along the SRPC', 'down and right along the SRPC', 'with the SRPC as it shifts right', 'with the LRPC as it shifts left'], correctAnswer: 1, explanation: 'Lower AD reduces inflation and raises unemployment, a movement down and to the right along the existing SRPC. Moving up and left would need AD to rise, and AD changes move the economy along the curves rather than shifting either one.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'An economy with a natural rate of 5% moves from point A (5% unemployment, 2% inflation) to point B (4%, 4%) and then to point C (5%, 4%). This path is best described as', options: ['an upward SRPC shift, then a move along it', 'two moves along one unchanging SRPC', 'a move along the SRPC, then an upward SRPC shift', 'a leftward LRPC shift, then a shift back'], correctAnswer: 2, explanation: 'Going from A to B trades lower unemployment for higher inflation along the SRPC; going from B to C keeps inflation at 4% while unemployment returns to 5%, which requires the SRPC to shift up as expectations adjust. A and C cannot lie on one SRPC, and the LRPC stays at 5% throughout.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'In the short run, the Phillips curve shows that', options: ['falling unemployment comes with rising inflation', 'lower unemployment tends to come with lower inflation', 'inflation and unemployment are unrelated in the short run', 'higher inflation tends to come with higher unemployment'], correctAnswer: 0, explanation: 'The SRPC slopes downward: when AD pushes unemployment down, inflation rises. Lower unemployment with lower inflation, or higher inflation with higher unemployment, would require an upward slope, and the short-run curve exists precisely because the two are related.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'Which event causes a movement along an existing short-run Phillips curve rather than a shift of it?', options: ['A rise in the inflation rate people expect', 'A sharp increase in world oil prices', 'A decrease in government spending', 'A major gain in labor productivity'], correctAnswer: 2, explanation: 'Lower government spending changes AD, which moves the economy along the SRPC. Changes in expected inflation, oil price shocks, and productivity gains alter costs or expectations and shift the SRPC itself.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'Which change would shift the long-run Phillips curve to the left?', options: ['Workers expect higher inflation', 'Online job boards shorten job searches', 'Consumer spending rises sharply', 'The central bank cuts interest rates'], correctAnswer: 1, explanation: 'Faster job matching reduces frictional unemployment, lowering the natural rate, so the vertical LRPC moves left. Higher expected inflation shifts the SRPC, and changes in spending or interest rates move the economy along the SRPC without changing the natural rate.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'During stagflation, a central bank that raises interest rates to fight inflation will most likely', options: ['bring unemployment down quickly as well', 'shift the LRPC permanently to the right', 'shift the SRPC right as costs rise', 'push unemployment even higher for a time'], correctAnswer: 3, explanation: 'Contractionary policy lowers AD, moving the economy down and right along the SRPC, so inflation eases but unemployment rises further in the short run. It cannot lower both at once, it does not change the natural rate, and it works through demand rather than shifting the SRPC.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'A wave of new technology lowers production costs across the economy. On the Phillips curve graph,', options: ['the SRPC shifts left, reducing inflation at each unemployment rate', 'a rightward SRPC shift raises inflation at each unemployment rate', 'the economy moves up and to the left along the SRPC', 'the LRPC shifts right, raising the natural rate'], correctAnswer: 0, explanation: 'A favorable supply shock lets the economy have lower inflation at every unemployment rate, shifting the SRPC left (down). A rightward shift reflects an adverse shock, movement up the SRPC comes from rising AD, and lower costs do not raise the natural rate.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'A point on the SRPC to the left of the LRPC corresponds, in the AD-AS model, to', options: ['a recessionary output gap', 'long-run equilibrium', 'an inflationary gap', 'a negative supply shock'], correctAnswer: 2, explanation: 'Left of the LRPC, unemployment is below the natural rate, which means output is above potential: an inflationary gap. A recessionary gap lies to the right of the LRPC, long-run equilibrium is on the LRPC, and a supply shock shifts the SRPC rather than locating a point.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  { question: 'Over two years, unemployment rises from 5% to 8% while inflation rises from 3% to 7%. In the Phillips curve model, this is best explained by', options: ['a movement along the SRPC', 'a rightward shift of the SRPC', 'a leftward shift of the SRPC', 'a leftward shift of the LRPC'], correctAnswer: 1, explanation: 'Unemployment and inflation rising together is stagflation, which shows up as the SRPC shifting right after an adverse supply shock. A movement along the SRPC moves the two in opposite directions, a leftward SRPC shift lowers inflation, and a leftward LRPC shift would lower the natural rate.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 2, part: 1 },
  { question: 'Why is there no lasting trade-off between inflation and unemployment?', options: ['The central bank targets zero inflation over the long run', 'Workers keep ignoring changes in the overall price level', 'Firms hold prices fixed once output reaches full capacity', 'Expectations adjust, so wages catch up with actual prices'], correctAnswer: 3, explanation: 'When inflation runs above what people expected, workers and firms revise their expectations and wages rise to match, eroding any employment gain. Central banks typically target low positive inflation rather than zero, workers do eventually notice price changes, and firms raise prices as the economy nears capacity.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-phillips-curve', formSet: 1, part: 1 },
  // ── Domain: financial-sector · macro-money-banking ───────────────────
  { question: 'A restaurant menu lists every dish in dollars so diners can quickly compare what each meal is worth. Here money is serving as a', options: ['medium of exchange', 'store of value', 'unit of account', 'source of liquidity'], correctAnswer: 2, explanation: 'Using money as a common yardstick for comparing values is its role as a unit of account. It acts as a medium of exchange only when the meal is actually paid for, as a store of value when it is saved for later, and liquidity is a property of assets rather than a function of money.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'A teenager keeps \\$300 from a summer job in a bank account to spend next year. Money is serving mainly as a', options: ['unit of account', 'medium of exchange', 'measure of liquidity', 'store of value'], correctAnswer: 3, explanation: 'Holding money to preserve purchasing power for future use is its store-of-value function. No purchase is being made (medium of exchange), no prices are being compared (unit of account), and liquidity describes how easily an asset converts to cash.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'Which of the following is included in M1?', options: ['A \\$5,000 certificate of deposit', 'Funds in a checking account', 'A credit card\'s unused limit', 'Shares of a stock index fund'], correctAnswer: 1, explanation: 'Checkable (demand) deposits are part of M1 along with currency. A certificate of deposit is a time deposit counted only in M2, unused credit is a borrowing option rather than money, and stock shares are financial assets outside the money supply.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'Which asset is part of M2 but not part of M1?', options: ['Coins and paper currency held by the public', 'A demand deposit at a commercial bank', 'A small-denomination time deposit', 'A Treasury bond held by a household'], correctAnswer: 2, explanation: 'Small time deposits such as CDs are less liquid than checkable deposits, so they are in M2 but not M1. Currency and demand deposits are in both M1 and M2, and government bonds are not part of either measure.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'Which list orders these assets from most liquid to least liquid?', options: ['House, CD, checking deposit, cash', 'Checking deposit, cash, house, CD', 'CD, cash, checking deposit, house', 'Cash, checking deposit, CD, house'], correctAnswer: 3, explanation: 'Cash is already money, a checking deposit can be spent almost instantly, a CD has a fixed term and early-withdrawal penalties, and a house takes time and cost to sell. The other orderings misplace cash or put the house ahead of more liquid assets.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'The required reserve ratio is 25%. What is the simple money multiplier?', options: ['4', '0.25', '25', '1.33'], correctAnswer: 0, explanation: 'Money multiplier = 1 ÷ reserve ratio = 1 ÷ 0.25 = 4. The value 0.25 is the reserve ratio itself, 25 confuses the percentage with the multiplier, and 1.33 divides by the share lent out (0.75) instead of the share held.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'A bank has \\$500,000 in deposits and \\$80,000 in reserves, and the reserve requirement is 10%. What are its excess reserves?', options: ['\\$50,000', '\\$30,000', '\\$80,000', '\\$420,000'], correctAnswer: 1, explanation: 'Required reserves are 10% × \\$500,000 = \\$50,000, so excess reserves are \\$80,000 − \\$50,000 = \\$30,000. Fifty thousand is the required amount, \\$80,000 is total reserves, and \\$420,000 subtracts reserves from deposits.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'A bank with no excess reserves receives a new \\$2,000 cash deposit, and the reserve requirement is 20%. How much can this single bank now lend?', options: ['\\$2,000', '\\$400', '\\$1,600', '\\$8,000'], correctAnswer: 2, explanation: 'The bank must keep 20% × \\$2,000 = \\$400 as required reserves and can lend the \\$1,600 of excess reserves. Lending all \\$2,000 ignores the requirement, \\$400 is the amount it must hold, and \\$8,000 is the whole banking system\'s potential, not one bank\'s.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'Someone deposits \\$2,000 of cash that was held at home. The reserve requirement is 20% and banks lend all excess reserves. What is the maximum increase in the money supply created by the banking system\'s new loans?', options: ['\\$10,000', '\\$1,600', '\\$2,000', '\\$8,000'], correctAnswer: 3, explanation: 'The deposit creates \\$1,600 of excess reserves, and the multiplier of 1 ÷ 0.2 = 5 allows up to 5 × \\$1,600 = \\$8,000 of new loans and deposits. Moving cash into a checking account only changes the form of money, so the full \\$10,000 of deposits overstates new money; \\$1,600 stops after the first bank.', difficulty: 'hard', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'The Federal Reserve buys \\$10 million of Treasury bonds from a household, which deposits the payment in its bank. The reserve requirement is 10%. What is the maximum increase in the money supply?', options: ['\\$90 million', '\\$100 million', '\\$10 million', '\\$1 million'], correctAnswer: 1, explanation: 'The household\'s new \\$10 million deposit is new money, and the \\$9 million of excess reserves can support up to \\$90 million of loans, for a total of \\$100 million. Ninety million counts only the loans, \\$10 million ignores lending, and \\$1 million is the required reserve.', difficulty: 'hard', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'A household owns \\$2 million in assets but holds only about \\$5,000 in money. Which of its assets most likely counts as money?', options: ['Its checking account balance', 'The market value of its house', 'Its retirement account invested in stocks', 'Its monthly salary from its jobs'], correctAnswer: 0, explanation: 'Checkable deposits are part of the money supply because they can be spent directly. A house and a stock portfolio are wealth but not money, and a salary is income, a flow over time rather than a stock of money held.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'A bank has deposits of \\$1,000,000, required reserves of \\$100,000, no excess reserves, and loans of \\$900,000. The reserve requirement is 10%. A customer withdraws \\$50,000 in cash. Immediately afterward, the bank', options: ['is short of required reserves by \\$50,000', 'has excess reserves of \\$5,000', 'is short of required reserves by \\$45,000', 'has excess reserves of \\$50,000'], correctAnswer: 2, explanation: 'Deposits fall to \\$950,000 and reserves fall to \\$50,000, while required reserves are now 10% × \\$950,000 = \\$95,000, a shortfall of \\$45,000. A \\$50,000 shortfall forgets that required reserves also fall, and the bank cannot have excess reserves after losing reserves it needed.', difficulty: 'hard', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'If the reserve requirement is cut from 25% to 12.5%, the simple money multiplier', options: ['falls from 8 to 4', 'rises from 4 to 8', 'increases from 4 to 5', 'stays at 4'], correctAnswer: 1, explanation: 'The multiplier is 1 ÷ 0.25 = 4 before and 1 ÷ 0.125 = 8 after, so it doubles. A lower requirement lets banks lend more of each deposit, so the multiplier cannot fall or stay the same, and a rise only to 5 misapplies the formula.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'In a barter economy, a farmer who wants shoes must find a shoemaker who happens to want wheat. Money solves this problem by serving as a', options: ['medium of exchange', 'store of value', 'unit of account', 'form of collateral'], correctAnswer: 0, explanation: 'Money avoids the need for a double coincidence of wants because both sides accept it in trade, which is its role as a medium of exchange. Storing value and measuring prices are separate functions, and collateral secures loans rather than enabling trade.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'Banks choose to hold some excess reserves, and households keep more cash instead of depositing it. Compared with the simple money multiplier, actual money creation will be', options: ['larger than the formula would predict', 'exactly what the formula predicts', 'smaller than the formula predicts', 'unrelated to bank lending decisions'], correctAnswer: 2, explanation: 'The simple multiplier assumes every dollar of excess reserves is lent and every loan is redeposited, so excess reserves and cash held outside banks shrink actual expansion. Expansion cannot exceed the formula\'s maximum, and lending decisions are exactly what drives it.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  { question: 'Market interest rates rise from 3% to 5%. What happens to the prices of previously issued bonds that pay a fixed 3%?', options: ['Their prices fall, since new debt pays more', 'Their prices rise, since rates are higher', 'Their prices stay fixed at face value', 'Their prices rise, since they are safer'], correctAnswer: 0, explanation: 'Buyers will not pay full price for a 3% bond when new bonds pay 5%, so older bonds\' prices fall until their yield matches the market: bond prices and interest rates move inversely. Prices of existing bonds do change with market rates, and nothing in the scenario makes the old bonds safer.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 2, part: 1 },
  { question: 'In economics, the liquidity of an asset refers to', options: ['how much interest the asset pays each year', 'how risky the asset is compared with bonds', 'how widely the asset is used in trade abroad', 'how easily it becomes cash without losing value'], correctAnswer: 3, explanation: 'Liquidity measures how quickly and cheaply an asset can be turned into spendable money. Interest paid, risk, and international use are separate characteristics; cash is perfectly liquid even though it pays no interest.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-money-banking', formSet: 1, part: 1 },
  // ── Domain: financial-sector · macro-monetary-policy ─────────────────
  { question: 'To fight a recession using open market operations, the Federal Reserve should', options: ['sell government securities', 'raise the discount rate it charges', 'buy government securities', 'raise the reserve requirement'], correctAnswer: 2, explanation: 'Buying securities adds reserves to the banking system, expanding the money supply and lowering interest rates. Selling securities, raising the discount rate, and raising the reserve requirement are all contractionary.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'The Fed sells bonds on the open market under a limited-reserves system. Which sequence follows?', options: ['Reserves fall, rates fall, investment rises, AD shifts right', 'Reserves fall, rates rise, investment falls, AD shifts left', 'Reserves fall, rates rise, investment rises, AD shifts right', 'Reserves rise, rates fall, investment rises, AD shifts right'], correctAnswer: 1, explanation: 'Buyers pay the Fed out of bank deposits, draining reserves and the money supply, which raises interest rates, discourages investment, and shifts AD left. Falling rates, rising investment, or rising reserves all describe an open market purchase, not a sale.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'In the money market graph for a limited-reserves system, the Fed increases the money supply. The money supply curve', options: ['shifts right, and the nominal interest rate falls', 'shifts left, and the nominal interest rate rises', 'shifts right, and the nominal interest rate rises', 'shifts right, and money demand shifts left'], correctAnswer: 0, explanation: 'A larger money supply shifts the vertical MS curve right, and the nominal interest rate falls along the downward-sloping money demand curve. A leftward shift would be contractionary, the rate cannot rise when supply increases with demand unchanged, and money demand depends on the price level, income, and the rate, not on the supply curve.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'Nominal GDP climbs as the economy expands, and the money supply is unchanged. In the money market,', options: ['money demand shifts left and the interest rate falls', 'money supply shifts right and the interest rate falls', 'money demand shifts right and the interest rate falls', 'money demand shifts right and the interest rate rises'], correctAnswer: 3, explanation: 'Higher nominal income means people need more money for transactions, so money demand shifts right and, with a fixed supply, the nominal interest rate rises. Money demand does not fall with more income, the money supply is set by the Fed rather than by GDP, and a rightward demand shift cannot lower the rate.', difficulty: 'hard', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'In today\'s ample-reserves framework, the Fed\'s main tool for raising its policy rate is to', options: ['sell large amounts of bonds to drain reserves', 'raise the interest rate it pays on reserve balances', 'increase the reserve requirement on deposits', 'lower the discount rate it charges banks'], correctAnswer: 1, explanation: 'With reserves plentiful, small open market operations barely move rates, so the Fed raises the interest it pays on reserves, which sets a floor that pulls the federal funds rate up. Raising the reserve requirement is not used in this framework, and lowering the discount rate would be expansionary.', difficulty: 'hard', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'The discount rate is the interest rate that', options: ['banks charge one another for overnight loans', 'banks charge their most creditworthy customers', 'the Treasury pays on its newly issued bonds', 'the Fed charges banks for short-term loans'], correctAnswer: 3, explanation: 'The discount rate is what the Federal Reserve charges banks that borrow from it directly. The overnight rate between banks is the federal funds rate, the rate for top customers is a commercial lending rate, and Treasury yields are set in the bond market.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'Bank A lends its excess reserves overnight to Bank B. The interest rate Bank B pays on this loan is', options: ['the discount rate', 'the federal funds rate', 'the prime rate', 'the interest rate on reserves'], correctAnswer: 1, explanation: 'Overnight lending of reserves between banks takes place at the federal funds rate, which the Fed targets. The discount rate applies to loans from the Fed itself, the prime rate is charged to business customers, and interest on reserves is what the Fed pays banks.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'Inflation is running well above the Fed\'s target. Which pair of actions is consistent with contractionary monetary policy?', options: ['Buy bonds and raise the discount rate', 'Lower the reserve requirement and sell bonds', 'Sell bonds and raise the discount rate', 'Buy bonds and lower the interest on reserves'], correctAnswer: 2, explanation: 'Selling bonds drains reserves and raising the discount rate makes borrowing reserves costlier, so both tighten money and raise interest rates. Each other pair mixes in an expansionary action: buying bonds, lowering the reserve requirement, or cutting the interest paid on reserves.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'In an economy with ample reserves, the central bank buys bonds and bank reserves rise, but the overnight lending rate barely changes. Why?', options: ['Extra liquidity does little to rates when banks hold plenty', 'Bond purchases push interest rates up under ample reserves', 'Banks are required to hold all of the new reserves they get', 'The money supply cannot increase once reserves are ample'], correctAnswer: 0, explanation: 'When banks already hold more reserves than they need, adding more does little to the rate they charge each other; the central bank moves rates by changing its administered rates, such as interest on reserves. Bond purchases do not raise rates, banks are not required to hold every new reserve dollar, and the money supply can still grow.', difficulty: 'hard', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'A recession begins while Congress is deadlocked over the federal budget. Why might monetary policy respond sooner than fiscal policy?', options: ['Monetary policy affects spending with no time lag', 'The Fed can directly hire unemployed workers', 'Monetary policy needs approval from the President', 'The FOMC acts without new legislation'], correctAnswer: 3, explanation: 'The FOMC can change its policy stance at a scheduled or emergency meeting, without waiting for Congress to pass a law. Monetary policy still takes months to affect spending, the Fed does not hire workers to stimulate demand, and it does not need presidential approval.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'Velocity is constant, real output grows 2% per year, and the money supply grows 7% per year. According to the quantity theory of money, inflation is about', options: ['5%', '7%', '9%', '2%'], correctAnswer: 0, explanation: 'With constant velocity, MV = PQ implies money growth ≈ inflation + real growth, so inflation ≈ 7% − 2% = 5%. Seven percent ignores real growth, 9% adds the rates, and 2% is the real growth rate.', difficulty: 'hard', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'The money supply is \\$2 trillion, velocity is 5, and real output is \\$8 trillion in base-year prices. Using MV = PQ, what is the price level?', options: ['0.8', '1.25', '4', '2.5'], correctAnswer: 1, explanation: 'MV = \\$2 trillion × 5 = \\$10 trillion, so P = \\$10 trillion ÷ \\$8 trillion = 1.25. The value 0.8 inverts the ratio, 4 divides real output by the money supply, and 2.5 divides velocity by M.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'The Fed lowers its policy rate during a recession. In the short run, what is the expected result?', options: ['Real output rises and the price level falls', 'Real output falls and the price level rises', 'Real output and the price level both rise', 'Real output is unchanged; the price level falls'], correctAnswer: 2, explanation: 'Lower rates boost investment and consumption, shifting AD right along the upward-sloping SRAS, so both output and the price level rise. A falling price level would require AD to fall, and falling output with rising prices describes an adverse supply shock.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'In the long run, a permanent increase in the growth rate of the money supply mainly raises', options: ['the inflation rate', 'real GDP', 'the natural rate of unemployment', 'productivity growth'], correctAnswer: 0, explanation: 'Money is neutral in the long run: once wages and prices adjust, faster money growth shows up as higher inflation rather than more output. Real GDP, the natural rate of unemployment, and productivity depend on real resources and technology.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'Under ample reserves, the Fed lowers the interest rate it pays on reserve balances. Banks will most likely', options: ['lend less, since holding reserves earns more', 'lend more, since holding reserves earns less', 'raise the rates they charge borrowers', 'hold more reserves at the Fed'], correctAnswer: 1, explanation: 'A lower return on parked reserves makes lending to households and firms relatively more attractive, so banks lend more and market rates fall. Holding reserves now earns less, not more, so banks would hold fewer reserves and charge lower, not higher, rates.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  { question: 'When the Fed sells bonds in large quantities, what happens to bond prices and interest rates?', options: ['Bond prices rise and interest rates fall', 'Bond prices and interest rates both rise', 'Bond prices and interest rates both fall', 'Bond prices fall and interest rates rise'], correctAnswer: 3, explanation: 'Adding to the supply of bonds pushes their prices down, and because bond prices and yields move inversely, interest rates rise. Prices and rates cannot move in the same direction for existing bonds, and rising prices with falling rates describes a Fed purchase.', difficulty: 'medium', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 2, part: 1 },
  { question: 'In the money market graph, the vertical axis measures', options: ['the real interest rate', 'the price level', 'the nominal interest rate', 'the quantity of money'], correctAnswer: 2, explanation: 'The money market determines the nominal interest rate, the opportunity cost of holding money. The real interest rate is on the loanable funds graph, the price level is on the AD-AS graph, and the quantity of money is on the horizontal axis.', difficulty: 'easy', domain: 'financial-sector', topicSlug: 'macro-monetary-policy', formSet: 1, part: 1 },
  // ── Domain: stabilization · macro-fiscal-policy ──────────────────────
  { question: 'The economy is in a recessionary gap. Which discretionary fiscal action is appropriate?', options: ['Raising personal income tax rates', 'Cutting federal spending on highways', 'Increasing federal spending on highways', 'Lowering the federal funds rate target'], correctAnswer: 2, explanation: 'More government purchases raise aggregate demand, helping close a recessionary gap. Raising taxes and cutting spending are contractionary, and changing the federal funds rate target is monetary policy, not fiscal policy.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'Inflation is rising rapidly because real output is above potential. An appropriate fiscal response is to', options: ['cut taxes or increase government spending', 'raise taxes or cut government spending', 'have the Fed buy bonds to expand the money supply', 'increase transfer payments to households'], correctAnswer: 1, explanation: 'Contractionary fiscal policy (higher taxes or lower spending) shifts AD left to close an inflationary gap. Tax cuts, more spending, and larger transfers would add to demand, and Fed bond purchases are expansionary monetary policy.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'Which of the following is an automatic stabilizer?', options: ['A one-time stimulus bill passed during a slump', 'A Fed decision to cut interest rates in a slump', 'A new highway program approved during a slump', 'Unemployment insurance payments that rise in a slump'], correctAnswer: 3, explanation: 'Unemployment insurance pays out more whenever layoffs rise, without any new vote, which cushions falling spending. A stimulus bill and a new highway program require legislation (discretionary policy), and a rate cut is monetary policy.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'During an economic boom, household incomes rise, and revenue from a progressive income tax rises even faster. This', options: ['worsens the boom by raising government spending', 'has no effect, since tax rates were not changed by law', 'dampens the boom by slowing growth in after-tax pay', 'is discretionary policy, since Congress set the brackets'], correctAnswer: 2, explanation: 'As incomes rise, more income falls into higher brackets, so taxes take a growing share and disposable income grows more slowly, restraining spending. This happens automatically without new legislation, which is what makes it an automatic stabilizer rather than discretionary policy, and it does not raise government spending.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'Why do economists consider automatic stabilizers useful?', options: ['They act without new legislation', 'They eliminate the business cycle completely', 'They reduce the national debt during recessions', 'They work through the Federal Reserve'], correctAnswer: 0, explanation: 'Automatic stabilizers respond to the business cycle immediately, avoiding the recognition and legislative lags of discretionary policy. They soften fluctuations rather than eliminating them, they increase deficits during recessions, and they are part of fiscal policy, not the Fed\'s tools.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'The government finances a larger budget deficit by borrowing. In the loanable funds market, what is the expected result?', options: ['The real interest rate falls and private investment rises', 'The real interest rate rises and private investment falls', 'The real interest rate rises and private investment rises', 'The real interest rate is unchanged and investment rises'], correctAnswer: 1, explanation: 'Government borrowing competes with private borrowers for loanable funds, raising the real interest rate, and the higher rate discourages private investment: crowding out. A falling or unchanged rate would require less competition for funds, and investment cannot rise when borrowing costs climb.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'In which situation is crowding out from deficit spending likely to be largest?', options: ['A deep recession has left many resources idle', 'Interest rates are near zero and banks hold large reserves', 'The economy is near full employment with high interest rates', 'Private investment demand is very weak and pessimistic'], correctAnswer: 2, explanation: 'Near full employment, extra government borrowing competes for scarce funds and resources, so interest rates rise and private investment falls the most. In a deep recession, with near-zero rates, or with weak investment demand, there is little private borrowing to displace.', difficulty: 'hard', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'This year a government spends \\$4.5 trillion and collects \\$3.8 trillion in taxes. Last year\'s national debt was \\$20 trillion. This year\'s', options: ['deficit is \\$0.7 trillion and the debt falls to \\$19.3 trillion', 'surplus is \\$0.7 trillion and the debt falls to \\$19.3 trillion', 'deficit is \\$20.7 trillion and the debt rises by \\$0.7 trillion', 'deficit is \\$0.7 trillion and the debt rises to \\$20.7 trillion'], correctAnswer: 3, explanation: 'Spending exceeds revenue by \\$0.7 trillion, a deficit, and each deficit adds to the accumulated debt, which becomes \\$20.7 trillion. A deficit never lowers the debt, spending more than revenue is not a surplus, and the deficit is the annual gap, not the debt total.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'A government runs a budget surplus in a given year when', options: ['tax revenue exceeds government spending in a year', 'government spending exceeds tax revenue in a year', 'the national debt exceeds annual GDP', 'exports exceed imports in a year'], correctAnswer: 0, explanation: 'A surplus means revenue is greater than spending for the year, which allows debt to be paid down. Spending above revenue is a deficit, the debt-to-GDP ratio is a separate measure, and exports exceeding imports is a trade surplus.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'A recession is recognized in March, Congress passes a stimulus package in October, and most of the money is spent the following year. This illustrates', options: ['crowding out from government borrowing', 'time lags that limit discretionary fiscal policy', 'the automatic stabilizer effect of taxes', 'the Fed\'s independence from Congress'], correctAnswer: 1, explanation: 'Delays in recognizing the problem, passing legislation, and spending the funds are the time lags that can make discretionary fiscal policy arrive too late. The scenario says nothing about interest rates or private investment, involves no automatic mechanism, and concerns Congress rather than the Fed.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'In the AD-AS model, expansionary fiscal policy used to close a recessionary gap is shown as', options: ['SRAS shifting right toward potential output', 'LRAS shifting left toward the current output', 'AD shifting left away from potential output', 'AD shifting right toward potential output'], correctAnswer: 3, explanation: 'Higher government spending or lower taxes raise total spending, shifting AD right until output reaches potential. Demand-side fiscal policy does not shift SRAS, potential output does not shrink to meet a slump, and a leftward AD shift would widen the gap.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'Congress increases transfer payments to low-income households by \\$30 billion. Compared with a \\$30 billion increase in government purchases, the effect on aggregate demand is', options: ['larger, because recipients spend every dollar of it', 'identical, because both cost the same \\$30 billion', 'smaller, because recipients save part of it', 'zero, because transfers are excluded from GDP'], correctAnswer: 2, explanation: 'Transfers work like a tax cut: households save part of the money before the first round of spending, so the effect is smaller than a direct purchase. Equal cost does not mean equal impact, and although transfers are not counted in GDP, the spending they finance is.', difficulty: 'hard', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'Persistent government deficits keep real interest rates elevated for many years. The most likely long-run consequence is', options: ['a smaller capital stock and slower economic growth', 'a larger capital stock and faster economic growth', 'a lower price level and higher real wages', 'a permanent fall in the natural rate of unemployment'], correctAnswer: 0, explanation: 'Higher real interest rates crowd out private investment in plant and equipment, so the capital stock grows more slowly and so does potential output. Less investment cannot enlarge the capital stock, and deficits do not lower the price level or the natural rate of unemployment.', difficulty: 'hard', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'In the United States, discretionary fiscal policy is set by', options: ['the Federal Reserve', 'Congress and the President', 'the Supreme Court', 'state governors'], correctAnswer: 1, explanation: 'Federal taxing and spending decisions require legislation passed by Congress and signed by the President. The Federal Reserve conducts monetary policy, the courts do not set budgets, and state governors manage state rather than national budgets.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'A country starts with no debt, runs deficits of \\$200 billion, \\$300 billion, and \\$100 billion in three straight years, and then runs a \\$150 billion surplus. What is its national debt?', options: ['\\$600 billion', '\\$750 billion', '\\$450 billion', '\\$150 billion'], correctAnswer: 2, explanation: 'The debt is the sum of past deficits minus surpluses: 200 + 300 + 100 − 150 = \\$450 billion. Six hundred billion ignores the surplus, \\$750 billion adds it, and \\$150 billion is the surplus alone.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  { question: 'Which is an example of contractionary discretionary fiscal policy?', options: ['Tax revenue rises automatically as incomes grow', 'The Fed sells bonds to reduce the money supply', 'Congress expands unemployment benefits in a slump', 'Congress raises the income tax rate to cool inflation'], correctAnswer: 3, explanation: 'A deliberate, legislated tax increase aimed at inflation is contractionary discretionary fiscal policy. Revenue rising on its own is an automatic stabilizer, a Fed bond sale is monetary policy, and expanding benefits is expansionary.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 2, part: 1 },
  { question: 'During a recession with no new legislation, the federal budget deficit tends to', options: ['grow, as tax revenue falls and transfers rise', 'shrink, as tax revenue falls and transfers rise', 'grow, as tax revenue rises while transfers fall', 'stay the same, since no new laws were enacted'], correctAnswer: 0, explanation: 'Automatic stabilizers kick in: lower incomes reduce tax collections while unemployment and welfare payments rise, so the deficit widens. Falling revenue and rising transfers cannot shrink a deficit, revenue does not rise in a recession, and the budget changes even without new laws.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy', formSet: 1, part: 1 },
  // ── Domain: stabilization · macro-fiscal-policy-tools ────────────────
  { question: 'With an MPC of 0.75, a \\$40 billion increase in government purchases can raise GDP by \\$160 billion. By how much could a \\$40 billion tax cut raise GDP?', options: ['\\$160 billion', '\\$120 billion', '\\$40 billion', '\\$30 billion'], correctAnswer: 1, explanation: 'The tax multiplier is MPC ÷ MPS = 0.75 ÷ 0.25 = 3, so the cut raises GDP by up to \\$120 billion. It is smaller than the \\$160 billion from purchases because households save a quarter of the tax cut before spending begins; \\$40 billion ignores the multiplier and \\$30 billion is only the first round of spending.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'The government raises its spending by \\$30 billion and raises taxes by \\$30 billion at the same time. With an MPC of 0.75, real GDP changes by', options: ['\\$0', '+\\$120 billion', '−\\$90 billion', '+\\$30 billion'], correctAnswer: 3, explanation: 'The spending increase adds 4 × \\$30 billion = \\$120 billion and the tax increase subtracts 3 × \\$30 billion = \\$90 billion, a net rise of \\$30 billion: the balanced-budget multiplier is 1. A balanced change is not neutral, and the other figures count only one of the two changes.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  { question: 'Why does an equal increase in government spending and taxes still raise real GDP?', options: ['Taxes have no effect on consumption', 'Government spending lowers interest rates', 'The spending multiplier exceeds the tax multiplier', 'Higher taxes raise the MPC'], correctAnswer: 2, explanation: 'Every dollar of new purchases enters spending directly, while part of each dollar of new taxes would have been saved anyway, so the expansionary effect outweighs the contractionary one. Taxes do reduce consumption, government borrowing tends to raise rather than lower rates, and taxes do not change the MPC.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'A tax takes 8% of a low-income family\'s income but only 2% of a high-income family\'s income. This tax is', options: ['regressive', 'progressive', 'proportional', 'marginal'], correctAnswer: 0, explanation: 'A tax that takes a larger share of income from lower earners is regressive. A progressive tax takes a larger share from higher earners, a proportional tax takes the same share from everyone, and marginal describes the rate on the next dollar, not the overall pattern.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  { question: 'A government offers tax credits to firms that buy new equipment and to workers who complete job training. In the long run, these policies are intended to', options: ['shift AD left by reducing household spending', 'shift SRAS left by raising firms\' business costs', 'shift the LRPC right by raising unemployment', 'shift LRAS right by raising productive capacity'], correctAnswer: 3, explanation: 'More physical capital and a more skilled workforce raise the economy\'s productive capacity, shifting LRAS right. The credits do not reduce household spending or raise business costs, and growth-oriented policies do not aim to raise unemployment.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'A large public investment program builds new roads and broadband networks. Its expected effects are to shift', options: ['AD left in the short run and LRAS right over time', 'AD right in the short run and LRAS right over time', 'only SRAS left, by raising input costs', 'only LRAS left, by crowding out investment'], correctAnswer: 1, explanation: 'The construction spending is government purchases that raise AD now, and the finished infrastructure lowers transport and communication costs, raising potential output later. Spending does not reduce AD, and better infrastructure lowers rather than raises costs; any crowding out offsets only part of the capacity gain.', difficulty: 'hard', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  { question: 'Which policy most directly increases an economy\'s human capital?', options: ['Cutting the corporate income tax rate', 'Building new ports and interstate highways', 'Expanding grants for job training', 'Lowering interest rates on business loans'], correctAnswer: 2, explanation: 'Human capital is the knowledge and skill of workers, so funding education and training builds it directly. Corporate tax cuts and cheaper loans target physical capital investment, and ports and highways are infrastructure.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'A government removes several costly regulations on businesses without changing spending or taxes. In the AD-AS model, this is expected to', options: ['shift SRAS right by lowering production costs', 'move the economy down along its AD curve', 'reduce AD by lowering consumer confidence', 'raise compliance costs and shift SRAS left'], correctAnswer: 0, explanation: 'Lower compliance costs reduce the cost of producing output, shifting SRAS (and potentially LRAS) right. The policy works through costs rather than by moving along AD or changing demand, and removing regulations lowers rather than raises compliance costs.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  { question: 'Supporters of a cut in business tax rates argue that it works on the supply side as well as the demand side. If they are right, the AD-AS model predicts that compared with a pure demand stimulus, the cut will', options: ['raise both output and prices more than a spending increase', 'raise output with less upward pressure on prices', 'lower output and raise prices through higher deficits', 'leave output unchanged and lower the price level'], correctAnswer: 1, explanation: 'If AS shifts right along with AD, output rises while the supply increase offsets some of the upward pressure on the price level. A larger rise in prices ignores the supply effect, and neither falling output nor unchanged output follows from rightward shifts of both curves.', difficulty: 'hard', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'As the national debt grows, a larger share of the federal budget goes to interest payments. One concern economists raise is that this', options: ['automatically lowers market interest rates', 'reduces the size of the budget deficit', 'shrinks the money supply by draining reserves', 'crowds out other budget priorities'], correctAnswer: 3, explanation: 'Dollars spent on interest are not available for programs or tax relief, limiting future fiscal choices. Heavy borrowing tends to raise rather than lower interest rates, larger interest costs widen rather than shrink the deficit, and interest payments do not drain bank reserves the way Fed bond sales do.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  { question: 'Assume an MPC of 0.8. Which fiscal action would raise aggregate demand the most?', options: ['A \\$10 billion cut in personal income taxes', 'A \\$10 billion increase in transfer payments', 'A \\$10 billion increase in government purchases', 'A \\$10 billion rise in both spending and taxes'], correctAnswer: 2, explanation: 'Purchases get the full spending multiplier of 5, raising GDP by up to \\$50 billion. A tax cut or transfer gets the tax multiplier of 4 (\\$40 billion) because part is saved, and a balanced rise in spending and taxes adds only \\$10 billion.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'To close an inflationary gap of \\$80 billion with an MPC of 0.8, the government could cut spending by \\$16 billion or, alternatively, raise taxes by', options: ['\\$20 billion', '\\$16 billion', '\\$64 billion', '\\$80 billion'], correctAnswer: 0, explanation: 'The tax multiplier is 0.8 ÷ 0.2 = 4, so a \\$20 billion tax increase lowers GDP by \\$80 billion. Sixteen billion uses the spending multiplier, which overstates the punch of a tax change, and \\$80 billion ignores the multiplier.', difficulty: 'hard', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  { question: 'Congress cuts taxes and raises spending during a recession. All else equal, the federal budget deficit', options: ['decreases', 'increases', 'stays the same', 'turns into a surplus'], correctAnswer: 1, explanation: 'Lower revenue combined with higher spending widens the gap between outlays and receipts, so the deficit grows. It cannot shrink or turn into a surplus when both changes add to borrowing.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'A government offers businesses a generous investment tax credit. In the loanable funds market, what is the expected effect?', options: ['The real interest rate falls as savers lend more', 'The real interest rate falls as firms borrow less', 'The real interest rate rises as firms seek more loans', 'The real interest rate is unchanged as firms save more'], correctAnswer: 2, explanation: 'The credit makes investment projects more profitable, so firms demand more loanable funds and the real interest rate rises. The policy targets borrowers rather than savers, so it raises demand rather than supply, and firms borrow more, not less.', difficulty: 'hard', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  { question: 'A tax break on interest earned in savings accounts is meant to', options: ['raise borrowing, which lifts real interest rates and slows investment', 'reduce saving, which boosts consumption and AD', 'shrink the money supply, which lifts nominal rates', 'raise saving, which lowers real interest rates and aids investment'], correctAnswer: 3, explanation: 'A higher after-tax return encourages saving, increasing the supply of loanable funds, lowering the real interest rate, and encouraging investment. The policy targets savers rather than borrowers, it encourages rather than discourages saving, and it has nothing to do with the Fed\'s control of the money supply.', difficulty: 'medium', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 1, part: 1 },
  { question: 'Which of the following is a supply-side fiscal policy?', options: ['Lowering taxes on business investment', 'Raising unemployment benefits', 'Buying bonds to lower interest rates', 'Increasing military purchases'], correctAnswer: 0, explanation: 'Supply-side policies change incentives to produce, and lower taxes on investment encourage firms to add capital, shifting AS right. Higher unemployment benefits and military purchases mainly shift AD, and bond purchases are monetary policy.', difficulty: 'easy', domain: 'stabilization', topicSlug: 'macro-fiscal-policy-tools', formSet: 2, part: 1 },
  // ── Domain: international · macro-open-economy ───────────────────────
  { question: 'In the loanable funds market, the price of loanable funds is', options: ['the nominal interest rate', 'the real interest rate', 'the foreign exchange rate', 'the aggregate price level'], correctAnswer: 1, explanation: 'Savers and borrowers care about purchasing power, so the loanable funds market is drawn against the real interest rate. The nominal rate is the price in the money market, the exchange rate is set in the foreign exchange market, and the price level belongs to the AD-AS model.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'Households decide to save a larger share of their incomes. In the loanable funds market,', options: ['demand rises and the real interest rate rises', 'supply falls and the real interest rate rises', 'supply rises and the real interest rate falls', 'demand falls and the real interest rate falls'], correctAnswer: 2, explanation: 'More saving increases the supply of loanable funds, pushing the real interest rate down. Saving is the supply side of the market, not the demand side, and more saving cannot reduce supply.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  { question: 'Foreign investors sharply increase their purchases of U.S. financial assets. In the U.S. loanable funds market, what is the expected result?', options: ['The real interest rate rises and investment falls', 'The real interest rate falls and investment falls', 'The real interest rate rises and investment rises', 'The real interest rate falls and investment rises'], correctAnswer: 3, explanation: 'A capital inflow adds to the supply of loanable funds, lowering the real interest rate and encouraging domestic investment. A rising rate would require more borrowing or less saving, and investment moves opposite to the real interest rate along the demand curve.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'The U.S. government increases its budget deficit. Working through the loanable funds and foreign exchange markets, what happens to the dollar and to U.S. net exports?', options: ['The dollar depreciates and net exports rise', 'The dollar appreciates and net exports fall', 'The dollar appreciates and net exports rise', 'The dollar depreciates and net exports fall'], correctAnswer: 1, explanation: 'Government borrowing raises the U.S. real interest rate, attracting foreign capital; the demand for dollars rises, the dollar appreciates, and pricier U.S. goods reduce net exports. A depreciation would require capital to flow out, and a stronger dollar lowers rather than raises net exports.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  { question: 'The Fed buys bonds to fight a recession, lowering U.S. interest rates. How do capital flows, the dollar, and U.S. net exports respond?', options: ['Capital flows in, the dollar appreciates, and net exports fall', 'Capital flows out, the dollar appreciates, and net exports rise', 'Capital flows out, the dollar depreciates, and net exports rise', 'Capital flows in, the dollar depreciates, and net exports fall'], correctAnswer: 2, explanation: 'Lower U.S. rates make foreign assets relatively attractive, so capital flows out, the demand for dollars falls, the dollar depreciates, and cheaper U.S. goods raise net exports. Inflows and appreciation follow higher rates, and a weaker dollar raises rather than lowers net exports.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'In an open economy, why do net exports reinforce expansionary monetary policy but partly offset expansionary fiscal policy?', options: ['Lower rates weaken the dollar, while deficits strengthen it', 'Deficits weaken the dollar, while lower rates strengthen it', 'Monetary policy raises import prices only in the long run', 'Fiscal policy always lowers exports by raising tariffs'], correctAnswer: 0, explanation: 'Monetary expansion lowers interest rates and depreciates the currency, boosting net exports, while deficit spending raises rates and appreciates the currency, reducing net exports. The reverse pairing gets both exchange-rate effects backward, and neither policy works through tariffs or only in the long run.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  { question: 'Real interest rates in the United States rise relative to those in Europe. Financial capital will tend to', options: ['flow out of the United States', 'stop moving between the two regions', 'flow equally in both directions', 'flow into the United States'], correctAnswer: 3, explanation: 'Investors seek the higher return, so financial capital flows toward U.S. assets. Outflows would follow lower U.S. rates, and a rate difference gives investors a reason to move funds in one direction rather than stop or balance.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'A graph of the loanable funds market shows the demand curve shifting right while the supply curve stays put. Which event could explain this?', options: ['Households increase their saving rate', 'The government borrows to finance a larger deficit', 'Foreign investors move funds into the country', 'The central bank sells government bonds'], correctAnswer: 1, explanation: 'Government borrowing adds to the demand for loanable funds. More household saving and capital inflows shift supply rather than demand, and a Fed bond sale is analyzed in the money market.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  { question: 'A government moves from a budget deficit to a surplus and begins paying down its debt. In the loanable funds market, the real interest rate', options: ['rises, discouraging private investment', 'rises, encouraging private investment', 'falls, encouraging private investment', 'falls, discouraging private investment'], correctAnswer: 2, explanation: 'With less government borrowing (or more public saving), funds are freed for private borrowers, so the real interest rate falls and private investment rises. A rising rate would come from more government borrowing, and investment moves opposite to the rate.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'Why is the loanable funds market drawn with the real interest rate rather than the nominal rate?', options: ['The Fed sets the nominal rate directly each day', 'Nominal rates never change in the long run', 'Real rates include expected inflation', 'Savers and borrowers care about returns after inflation'], correctAnswer: 3, explanation: 'Lending and borrowing decisions depend on the purchasing power of the return, which is the real rate. Nominal rates are what include expected inflation, the Fed targets only a short-term policy rate, and nominal rates do change over time.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  { question: 'To fight inflation, the Fed raises U.S. interest rates. Through the exchange-rate channel, what happens to the dollar and to aggregate demand?', options: ['The dollar appreciates, and lower net exports reduce AD further', 'The dollar depreciates, and higher net exports offset the policy', 'The dollar appreciates, and higher net exports offset the policy', 'The dollar is unaffected, since only fiscal policy moves the dollar'], correctAnswer: 0, explanation: 'Higher U.S. rates attract foreign capital, the dollar appreciates, and pricier U.S. goods lower net exports, reinforcing the drop in AD. Depreciation follows lower rates, an appreciation reduces rather than raises net exports, and monetary policy clearly moves the exchange rate.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'Which group supplies funds in the loanable funds market?', options: ['Firms borrowing to invest', 'Savers, including foreign savers', 'Governments that borrow', 'Banks borrowing from the Fed'], correctAnswer: 1, explanation: 'Supply comes from saving by households, firms, and foreigners who lend into the market. Investing firms and deficit-running governments are borrowers on the demand side, and Fed lending to banks is a money market and policy matter.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  { question: 'Expansionary fiscal policy would raise AD by \\$100 billion if interest rates and exchange rates did not change. Once crowding out and the exchange-rate channel are considered, the increase in AD is most likely', options: ['exactly the full \\$100 billion', 'more than the \\$100 billion', 'zero, since all spending is offset', 'less than \\$100 billion'], correctAnswer: 3, explanation: 'Higher interest rates reduce private investment and a stronger currency reduces net exports, so part of the stimulus is offset. The offset is partial, not total, and nothing in these channels adds to the original effect.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'Through the exchange-rate channel, a lower U.S. interest rate affects U.S. aggregate demand by', options: ['lowering net exports as the dollar weakens', 'raising imports as the dollar strengthens', 'raising net exports as the dollar weakens', 'lowering consumption as savings earn less'], correctAnswer: 2, explanation: 'Lower rates reduce the demand for dollar assets, the dollar depreciates, and U.S. goods become cheaper abroad, raising net exports. A weaker dollar raises rather than lowers net exports, the dollar does not strengthen when rates fall, and consumption effects are not part of the exchange-rate channel.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  { question: 'Which change shifts the demand for loanable funds to the left?', options: ['Firms grow pessimistic and cancel expansion plans', 'The government runs a larger budget deficit', 'An investment tax credit is introduced', 'New technology makes investment more profitable'], correctAnswer: 0, explanation: 'Fewer planned investment projects mean firms want to borrow less, shifting demand left. A larger deficit, an investment tax credit, and more profitable technology all increase borrowing and shift demand right.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-open-economy', formSet: 1, part: 1 },
  { question: 'After Congress passes a large tax cut financed by borrowing, U.S. real interest rates rise and foreign purchases of U.S. bonds increase. Which of the following would most likely follow?', options: ['A wider U.S. trade deficit', 'A narrower U.S. trade deficit', 'A weaker U.S. dollar abroad', 'Lower U.S. interest rates overall'], correctAnswer: 0, explanation: 'Foreign demand for U.S. bonds raises the demand for dollars, the dollar appreciates, and net exports fall, widening the trade deficit. The dollar strengthens rather than weakens, and the stem already says interest rates rose.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-open-economy', formSet: 2, part: 1 },
  // ── Domain: international · macro-international-trade-finance ────────
  { question: 'The exchange rate moves from \\$1 = 100 yen to \\$1 = 120 yen. The dollar has', options: ['depreciated against the yen', 'stayed constant in real terms', 'appreciated against the yen', 'been devalued by the Fed'], correctAnswer: 2, explanation: 'Each dollar now buys more yen, so the dollar has appreciated (and the yen has depreciated). A depreciation would mean the dollar buys fewer yen, the stem gives no price-level data for a real comparison, and the change comes from the currency market, not a Fed devaluation.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'One dollar now buys 0.8 euros instead of 0.9 euros. Which of the following is true?', options: ['U.S. goods become cheaper for European buyers', 'European goods become cheaper for American buyers', 'U.S. exports to Europe will tend to decline', 'U.S. imports from Europe will tend to increase'], correctAnswer: 0, explanation: 'The dollar has depreciated, so Europeans need fewer euros to buy each dollar\'s worth of U.S. goods. A weaker dollar makes European goods more expensive for Americans, so U.S. exports tend to rise and imports tend to fall.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },
  { question: 'In the foreign exchange market for U.S. dollars (priced in euros), European airlines order many more U.S.-made aircraft. What happens?', options: ['The dollar depreciates as the supply of dollars rises', 'The dollar depreciates as demand for dollars falls', 'The dollar appreciates as the supply of dollars falls', 'The dollar appreciates as demand for dollars rises'], correctAnswer: 3, explanation: 'Europeans need dollars to pay for U.S. aircraft, so the demand for dollars shifts right and the dollar appreciates. U.S. exports affect the demand side of the dollar market rather than its supply, and more demand cannot weaken the dollar.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'In the foreign exchange market for Japanese yen (priced in dollars), Americans sharply increase their purchases of Japanese cars. What happens?', options: ['The yen depreciates as the supply of yen rises', 'The yen appreciates as demand for yen rises', 'The yen depreciates as demand for yen falls', 'The yen appreciates as the supply of yen falls'], correctAnswer: 1, explanation: 'Americans must buy yen to pay for Japanese cars, so the demand for yen rises and the yen appreciates against the dollar. The extra purchases add to demand for yen rather than changing its supply, and higher demand cannot cause depreciation.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },
  { question: 'Mexico\'s inflation rate rises far above the U.S. inflation rate. All else equal, what happens in the foreign exchange market?', options: ['The peso depreciates against the dollar', 'The peso appreciates against the dollar', 'The peso is unaffected by relative inflation', 'The dollar depreciates against the peso'], correctAnswer: 0, explanation: 'Faster price growth makes Mexican goods relatively expensive, so foreigners buy fewer of them and demand fewer pesos, and the peso depreciates. A peso appreciation is the same as a dollar depreciation, so both get the direction backward, and relative inflation does affect currency values.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'Incomes in Europe rise rapidly, and Europeans buy more imported goods, including U.S. goods. What is the initial effect on the dollar and on U.S. net exports?', options: ['The dollar depreciates and U.S. net exports rise', 'The dollar appreciates and U.S. net exports fall', 'The dollar appreciates and U.S. net exports rise', 'The dollar depreciates and U.S. net exports fall'], correctAnswer: 2, explanation: 'Higher European purchases of U.S. goods raise U.S. exports and the demand for dollars, so the dollar appreciates while U.S. net exports increase. A depreciation would require weaker demand for dollars, and the triggering event is a rise, not a fall, in exports.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },
  { question: 'Which transaction is recorded in the U.S. current account?', options: ['A Japanese bank buys U.S. Treasury bonds', 'A U.S. investor buys shares in a French company', 'A Canadian firm builds a factory in Ohio', 'A U.S. firm imports \\$2 million of German machinery'], correctAnswer: 3, explanation: 'Trade in goods and services belongs in the current account, so imported machinery is recorded there. Purchases of bonds, stock, and foreign direct investment such as a new factory are asset transactions recorded in the financial account.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'A German automaker builds a new assembly plant in South Carolina. In the U.S. balance of payments, this is recorded as', options: ['a financial account inflow', 'a financial account outflow', 'a current account credit', 'a current account debit'], correctAnswer: 0, explanation: 'Foreign purchase of real assets in the United States is a financial (capital) account inflow to the U.S. It is not an outflow because money is coming in, and building a plant is an asset purchase, not trade in goods and services recorded in the current account.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },
  { question: 'A country runs a current account surplus of \\$150 billion. Assuming no statistical discrepancy, its financial account must show', options: ['a surplus of \\$150 billion', 'a deficit of \\$150 billion', 'a surplus of \\$300 billion', 'a balance of exactly zero'], correctAnswer: 1, explanation: 'The current and financial accounts sum to zero, so a \\$150 billion current account surplus is matched by a \\$150 billion financial account deficit (a net outflow of capital). A surplus in both is impossible under the identity, and doubling the figure has no basis.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'In one year, a country exports \\$400 billion of goods and services and imports \\$520 billion. Its net investment income from abroad is +\\$30 billion and net transfers are −\\$10 billion. What is its current account balance?', options: ['−\\$120 billion', '−\\$90 billion', '−\\$100 billion', '+\\$100 billion'], correctAnswer: 2, explanation: 'The current account adds the trade balance, net income, and net transfers: −120 + 30 − 10 = −\\$100 billion. The −\\$120 billion figure is only the trade balance, −\\$90 billion forgets the transfers, and +\\$100 billion flips the sign.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },
  { question: 'The dollar appreciates sharply against most currencies. In the AD-AS model for the United States, aggregate demand', options: ['shifts right as net exports rise', 'contracts as imports fall sharply', 'stays put since only prices change', 'shifts left as net exports fall'], correctAnswer: 3, explanation: 'A stronger dollar makes U.S. exports pricier abroad and imports cheaper at home, so net exports fall and AD shifts left. Imports rise rather than fall, net exports fall rather than rise, and a change in relative prices across countries does shift AD.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'Which person would add to the demand for U.S. dollars in the foreign exchange market?', options: ['An American tourist planning a trip to London', 'A British tourist bound for Florida', 'A U.S. importer buying Italian olive oil', 'A U.S. investor buying Brazilian bonds'], correctAnswer: 1, explanation: 'A British tourist must exchange pounds for dollars to spend in Florida, adding to the demand for dollars. The American tourist, the U.S. importer, and the U.S. investor all need foreign currency, so they supply dollars instead.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },
  { question: 'The Bank of Japan raises its interest rates while U.S. rates stay the same. What happens to the dollar relative to the yen?', options: ['It depreciates, as investors move funds into yen assets', 'It appreciates, as funds move into dollar assets', 'It depreciates, as Japanese exports become cheaper', 'It is unchanged, since U.S. rates did not move'], correctAnswer: 0, explanation: 'Higher Japanese returns draw financial capital toward yen assets, raising demand for yen and supply of dollars, so the dollar depreciates. Funds flow toward the higher rate, not away from it; Japanese exports do not get cheaper when the yen strengthens; and relative rates matter even if U.S. rates are unchanged.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'Which argument suggests that a U.S. trade deficit is not necessarily harmful?', options: ['Foreigners accumulate a growing stock of U.S. assets', 'Some U.S. factory jobs move to other countries', 'The matching capital inflows can fund U.S. investment', 'The U.S. depends more heavily on foreign lending'], correctAnswer: 2, explanation: 'A current account deficit is matched by financial inflows, which can finance productive investment in the United States. Growing foreign ownership, lost factory jobs, and dependence on foreign lending are the concerns critics raise about deficits.', difficulty: 'medium', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },
  { question: 'The exchange rate rises from \\$1.10 per euro to \\$1.25 per euro. A German car priced at 40,000 euros now costs an American buyer', options: ['\\$44,000, up from \\$40,000', '\\$32,000, down from \\$36,364', '\\$40,000, unchanged from before', '\\$50,000, up from \\$44,000'], correctAnswer: 3, explanation: 'Dollar cost = euro price × dollars per euro: 40,000 × 1.10 = \\$44,000 before and 40,000 × 1.25 = \\$50,000 after, because the euro appreciated. Dividing by the exchange rate gives the smaller figures, and the dollar price changes whenever the exchange rate does.', difficulty: 'hard', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 1, part: 1 },
  { question: 'When a country\'s currency depreciates, the currency', options: ['buys more units of foreign currency than before', 'buys fewer units of foreign currency than before', 'makes the country\'s imports cheaper for its residents', 'makes the country\'s exports more expensive abroad'], correctAnswer: 1, explanation: 'Depreciation means a unit of the currency exchanges for fewer units of foreign currency. Buying more foreign currency is appreciation. Because each unit buys less abroad, imports become more expensive for residents and the country\'s exports become cheaper for foreign buyers, not the reverse.', difficulty: 'easy', domain: 'international', topicSlug: 'macro-international-trade-finance', formSet: 2, part: 1 },

  // ── macro-aggregate-demand-supply (national-income) ──
  { question: 'When the price level falls, households need less money for everyday purchases, so they lend out the surplus; interest rates fall and investment spending rises. This chain of events explains', options: ['the interest-rate effect behind the downward slope of AD', 'the wealth effect behind the downward slope of AD', 'a rightward shift of AD caused by lower interest rates', 'a rightward shift of SRAS caused by lower interest rates'], correctAnswer: 0, explanation: 'A lower price level reduces the demand for money, which lowers interest rates and raises investment: the interest-rate effect, one reason AD slopes downward. The wealth effect works through the real value of money already held, and because the trigger is the price level, this is a movement along AD rather than a shift of AD or SRAS.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 1 },
  { question: 'In the AD–AS model, what is measured on the vertical axis?', options: ['The overall price level', 'The price of a single typical good', 'The economy\'s real interest rate', 'The level of nominal GDP'], correctAnswer: 0, explanation: 'The AD–AS model plots the overall price level, such as the GDP deflator, against real GDP. The price of one good belongs on a micro demand-and-supply graph, the real interest rate is on the loanable funds graph, and output (real, not nominal, GDP) is on the horizontal axis.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 1 },
  { question: 'Which of the following is counted in the government spending (G) component of aggregate demand?', options: ['Social Security checks mailed to retirees', 'A state paying a firm to repave a highway', 'A family buying a new car from a dealer', 'A firm building a new regional warehouse'], correctAnswer: 1, explanation: 'G counts government purchases of goods and services, such as paying for highway work. Social Security checks are transfer payments, which are not purchases of output, a family\'s car is consumption, and a firm\'s new warehouse is investment.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 1 },
  { question: 'Holding the U.S. price level constant, which of the following would shift U.S. aggregate demand to the right?', options: ['A rise in household saving at every income level', 'An appreciation of the dollar against the euro', 'A rise in national income in major trading partners', 'An increase in personal income tax rates'], correctAnswer: 2, explanation: 'Richer trading partners buy more U.S. exports, so net exports rise at every price level and AD shifts right. More saving means less consumption at every price level, a stronger dollar lowers net exports, and higher income taxes reduce consumption, which shift AD left.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 2 },
  { question: 'A rise in the overall price level reduces the quantity of real GDP demanded. On an AD–AS graph, this is shown as', options: ['a leftward shift of the entire AD curve', 'a movement up and to the left along AD', 'a rightward shift of the entire AD curve', 'a movement down and to the right along AD'], correctAnswer: 1, explanation: 'When the trigger is the price level itself, the economy moves along a fixed AD curve: a higher price level means a point up and to the left. Shifts of AD come from changes in C, I, G or NX at a given price level, and moving down and to the right would mean the price level fell.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 2 },
  { question: 'Congress raises personal income taxes while the price level is unchanged. Which best describes the effect on the AD–AS model?', options: ['Lower consumption moves the economy along AD', 'Higher tax revenue shifts AD to the right', 'Lower consumption shifts SRAS to the left', 'Lower consumption shifts AD to the left'], correctAnswer: 3, explanation: 'Higher taxes cut disposable income, so households consume less at every price level and AD shifts left. Because the price level did not trigger the change, it is a shift rather than a movement along AD, household taxes act on demand rather than on SRAS, and collecting more revenue does not raise spending.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 2 },
  { question: 'Suppose nominal wages and all other input prices adjusted instantly and fully to every change in the price level. The short-run aggregate supply curve would then', options: ['be horizontal at the current price level', 'slope downward in the same way as AD', 'be vertical at potential output, like LRAS', 'shift right each time the price level rose'], correctAnswer: 2, explanation: 'SRAS slopes upward only because sticky wages let a higher price level widen profit margins; if costs kept pace instantly, output would not respond to the price level and the curve would be vertical at potential output. A horizontal or downward-sloping curve has no basis in the model, and the price level moves along SRAS rather than shifting it.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 3 },
  { question: 'Which of the following would shift both the long-run and the short-run aggregate supply curves to the right?', options: ['A one-time drop in the world price of oil', 'A fall in the inflation that workers expect', 'A lasting rise in the capital stock', 'A sustained increase in government purchases'], correctAnswer: 2, explanation: 'A larger stock of capital raises the economy\'s productive capacity, so potential output grows and LRAS shifts right along with SRAS. A one-time oil price drop and lower expected inflation change costs but not capacity, so they move SRAS only, and government purchases shift AD.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 3 },
  { question: 'A one-year drought destroys much of a country\'s harvest, raising food and input costs. In the short run,', options: ['LRAS shifts left while SRAS stays put', 'SRAS and LRAS both shift to the left', 'SRAS shifts left while LRAS stays the same', 'AD shifts left while SRAS stays put'], correctAnswer: 2, explanation: 'A temporary cost shock makes production less profitable at every price level, so SRAS shifts left, but it does not change the economy\'s long-run capacity, so LRAS stays put. LRAS moves only with lasting changes in resources or technology, and the drought acts on costs rather than on spending.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 3 },
  { question: 'Short-run equilibrium real GDP is \\$14.6 trillion and potential GDP is \\$14.0 trillion. The economy has', options: ['an inflationary gap of \\$0.6 trillion', 'a recessionary gap of \\$0.6 trillion', 'an inflationary gap of \\$14.6 trillion', 'a long-run equilibrium at \\$14.6 trillion'], correctAnswer: 0, explanation: 'The output gap is Y − Yf = 14.6 − 14.0 = +0.6, so output is \\$0.6 trillion above potential: an inflationary gap. A recessionary gap would need output below potential, the gap is the difference rather than the level of output, and long-run equilibrium requires output to equal potential.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 4 },
  { question: 'On an AD–AS graph, AD and SRAS intersect at a level of real GDP to the left of the LRAS curve. Which of the following is true?', options: ['Unemployment exceeds its natural rate', 'Unemployment is below its natural rate', 'Unemployment equals its natural rate', 'Output exceeds full-employment output'], correctAnswer: 0, explanation: 'An equilibrium left of LRAS means output is below potential, a recessionary gap, so there is cyclical unemployment on top of natural unemployment. Unemployment below the natural rate and output above full employment describe an inflationary gap, and unemployment equals the natural rate only on LRAS.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 4 },
  { question: 'Equilibrium real GDP is \\$19.2 trillion and potential GDP is \\$20.0 trillion. Which describes the output gap?', options: ['+\\$0.8 trillion, an inflationary gap', '−\\$0.8 trillion, an inflationary gap', '+\\$0.8 trillion, a recessionary gap', '−\\$0.8 trillion, a recessionary gap'], correctAnswer: 3, explanation: 'Output gap = Y − Yf = 19.2 − 20.0 = −0.8 trillion; a negative gap means output is below potential, which is a recessionary gap. A positive value reverses the subtraction, and an inflationary gap would require output above potential.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 4 },
  { question: 'The marginal propensity to save is 0.2, and business investment rises by \\$30 billion. By how much does aggregate demand shift to the right?', options: ['\\$30 billion', '\\$120 billion', '\\$37.5 billion', '\\$150 billion'], correctAnswer: 3, explanation: 'The spending multiplier is 1 ÷ MPS = 1 ÷ 0.2 = 5, so AD shifts right by 5 × \\$30 billion = \\$150 billion. The \\$30 billion figure ignores the re-spending, \\$120 billion counts only the re-spending rounds without the initial \\$30 billion, and \\$37.5 billion divides by the MPC instead of multiplying by the multiplier.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 5 },
  { question: 'An economy has a \\$600 billion recessionary gap, and the MPC is 0.75. What increase in government spending would close the gap?', options: ['\\$600 billion', '\\$2,400 billion', '\\$450 billion', '\\$150 billion'], correctAnswer: 3, explanation: 'The multiplier is 1 ÷ (1 − 0.75) = 4, so the required spending is the gap divided by the multiplier: \\$600 billion ÷ 4 = \\$150 billion. Spending the full \\$600 billion ignores the multiplier, \\$450 billion multiplies the gap by the MPC, and \\$2,400 billion multiplies the gap by the multiplier instead of dividing.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 5 },
  { question: 'If the marginal propensity to consume rises from 0.8 to 0.9, what happens to the spending multiplier?', options: ['It halves, from 10 to 5', 'It shrinks, from 1.25 to 1.11', 'It doubles, from 5 to 10', 'It is unchanged, at 5'], correctAnswer: 2, explanation: 'The multiplier is 1 ÷ (1 − MPC): 1 ÷ 0.2 = 5 before and 1 ÷ 0.1 = 10 after, because more of each dollar is re-spent. Falling from 10 to 5 reverses the effect of a higher MPC, 1.25 and 1.11 come from dividing by the MPC, and the multiplier cannot stay the same when the MPC changes.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 5 },
  { question: 'Over one year, a country\'s price level falls while its real GDP rises. Which shift best explains both changes?', options: ['A rightward shift of SRAS', 'A rightward shift of AD', 'A leftward shift of AD', 'A leftward shift of SRAS'], correctAnswer: 0, explanation: 'A supply shift moves the price level and output in opposite directions, and a rightward SRAS shift lowers prices while raising output. Shifts of AD move the price level and output in the same direction, and a leftward SRAS shift raises prices while cutting output.', difficulty: 'medium', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 6 },
  { question: 'An economy is in an inflationary gap, and policymakers take no action. According to the AD–AS model, in the long run', options: ['AD shifts left as the rising prices discourage spending', 'nominal wages rise, SRAS shifts left, and output returns to potential', 'nominal wages stay fixed while LRAS shifts right to meet output', 'nominal wages fall, SRAS shifts right, and output rises further'], correctAnswer: 1, explanation: 'Tight labor markets push nominal wages up, which shifts SRAS left until output falls back to potential at a higher price level. Rising prices move the economy along AD rather than shifting it, LRAS does not move to meet output, and wages rise rather than fall in an inflationary gap.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 6 },
  { question: 'Equilibrium real GDP is below potential output. Which policy combination shifts aggregate demand in the appropriate direction?', options: ['Cutting government purchases and raising taxes', 'Raising taxes and reducing the money supply', 'Raising government purchases and cutting taxes', 'Cutting taxes and reducing the money supply'], correctAnswer: 2, explanation: 'Output below potential is a recessionary gap, which calls for expansionary policy that shifts AD right, such as more government purchases and lower taxes. Cutting purchases, raising taxes and shrinking the money supply are contractionary, and pairing a tax cut with a smaller money supply pushes AD in opposite directions.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 6 },
  { question: 'Which of the following events is most likely to cause stagflation in the short run?', options: ['A sharp increase in consumer confidence', 'A sharp decrease in government purchases', 'A sharp decrease in business tax rates', 'A sharp increase in world oil prices'], correctAnswer: 3, explanation: 'Stagflation, a higher price level with lower output, comes from a leftward SRAS shift, and a jump in world oil prices raises costs across the economy. Higher confidence and lower government purchases shift AD, moving prices and output together, and lower business taxes shift SRAS right.', difficulty: 'easy', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 1, part: 7 },
  { question: 'The MPC is 0.8. Starting from long-run equilibrium, business investment falls by \\$40 billion. Which best describes the short-run outcome?', options: ['AD shifts left by up to \\$200 billion, opening a recessionary gap', 'AD shifts left by \\$40 billion, opening a recessionary gap', 'AD shifts left by up to \\$200 billion, opening an inflationary gap', 'AD shifts left by up to \\$50 billion, opening a recessionary gap'], correctAnswer: 0, explanation: 'The multiplier is 1 ÷ 0.2 = 5, so AD shifts left by up to 5 × \\$40 billion = \\$200 billion, pushing output below potential: a recessionary gap. The \\$40 billion figure ignores the multiplier, \\$50 billion divides by the MPC, and output below potential is a recessionary rather than an inflationary gap.', difficulty: 'hard', domain: 'national-income', topicSlug: 'macro-aggregate-demand-supply', formSet: 2, part: 7 },
]

export function generateExitQuiz(count = 10, topicSlug?: string): { id: string; question: string; options: string[]; correctIndex: number; explanation: string; category: string }[] {
  let pool = macroQuestionPool
  if (topicSlug) pool = relevantPool(pool, topicSlug)
  return shuffleArray(pool).slice(0, count).map((q, i) => ({
    id: `${q.topicSlug}-q${i}`,
    question: q.question,
    options: q.options,
    correctIndex: q.correctAnswer,
    explanation: q.explanation,
    category: q.domain,
    topicSlug: q.topicSlug,
    partNumber: q.part,
  }))
}
